import{_ as e}from"./plugin-vue_export-helper-DlAUqK2U.js";import{c as l,a as n,o}from"./app-Ck-arJW_.js";const s={};function r(g,t){return o(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="ai-agent-面试" tabindex="-1"><a class="header-anchor" href="#ai-agent-面试"><span>AI Agent 面试</span></a></h1><h2 id="基础概念与核心组件" tabindex="-1"><a class="header-anchor" href="#基础概念与核心组件"><span>基础概念与核心组件</span></a></h2><h3 id="【简单】什么是-ai-agent-它和直接调用大模型-api-有什么区别-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【简单】什么是-ai-agent-它和直接调用大模型-api-有什么区别-⭐⭐⭐"><span>【简单】什么是 AI Agent？它和直接调用大模型 API 有什么区别？⭐⭐⭐</span></a></h3><p>AI Agent（智能体）是以大语言模型（LLM）为&quot;大脑&quot;的自主智能系统，能以&quot;<strong>用户目标 → Agent 规划 → Agent 执行 → 结果反馈</strong>&quot;的模式自主完成复杂任务。</p><p><strong>与直接调用大模型 API 的核心区别</strong>：</p><table><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">AI Agent</th><th style="text-align:left;">直接调用 LLM API</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>交互模式</strong></td><td style="text-align:left;">多步骤自主循环（规划→执行→反思）</td><td style="text-align:left;">单次问答（指令→生成→用户执行）</td></tr><tr><td style="text-align:left;"><strong>工具能力</strong></td><td style="text-align:left;">自主调用外部工具（搜索、API 等）</td><td style="text-align:left;">仅生成文本，无法执行操作</td></tr><tr><td style="text-align:left;"><strong>记忆能力</strong></td><td style="text-align:left;">具备短期/长期记忆，持续学习适应</td><td style="text-align:left;">无状态，每次独立交互</td></tr><tr><td style="text-align:left;"><strong>自主性</strong></td><td style="text-align:left;">主动拆解目标、动态调整计划</td><td style="text-align:left;">被动应答，依赖用户逐步指令</td></tr></tbody></table><p><strong>方案权衡：Agent 不是默认选项</strong></p><table><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">决策特征</th><th style="text-align:left;">适用边界</th><th style="text-align:left;">失效场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>直接 API 调用</strong></td><td style="text-align:left;">单次请求-响应，路径固定</td><td style="text-align:left;">分类、抽取、改写等封闭任务</td><td style="text-align:left;">需要外部数据或多步操作时无能为力</td></tr><tr><td style="text-align:left;"><strong>固定工作流</strong></td><td style="text-align:left;">开发者预定义节点与分支，LLM 只在节点内发挥</td><td style="text-align:left;">流程可预测、要求高确定性的业务</td><td style="text-align:left;">开放式任务、路径无法预先枚举</td></tr><tr><td style="text-align:left;"><strong>自主 Agent</strong></td><td style="text-align:left;">LLM 自主决定路径和工具调用</td><td style="text-align:left;">任务路径无法预先枚举</td><td style="text-align:left;">非确定性、成本高、易循环失控</td></tr></tbody></table><p>实测参考：内部客服场景同一&quot;查询物流状态&quot;任务，工作流方案成功率 94%、平均 Token 约 1.2k；Agent 自主方案成功率 81%、平均 Token 约 6.8k——<strong>路径封闭时，工作流在成功率和成本上双优</strong>。</p><p><strong>真实踩坑案例（Agent 循环失控）</strong>：</p><ul><li><strong>现象</strong>：客服 Agent 部分提问 P95 延迟达 47 秒，频繁超时。</li><li><strong>排查</strong>：Trace 回放发现 Agent 连续调用&quot;订单查询&quot;工具 3~5 次，每次参数略有差异，返回结果几乎相同。</li><li><strong>根因</strong>：工具描述只写了&quot;查询订单&quot;，未说明返回字段与终止语义，LLM 无法判断结果是否满足需求，于是反复重试。</li><li><strong>修复</strong>：① 重写工具描述，明确返回内容和&quot;无需重复调用&quot;的条件；② 增加重复检测——连续两轮调用同一工具且 Observation 相似度 &gt; 0.95 时强制进入总结。修复后 P95 延迟降至 9 秒。</li></ul><blockquote><p><strong>总结</strong>：Agent 与传统 AI 的本质差异在于——传统 AI 执行预定义规则的单点任务，Agent 能理解自然语言指令，自主将复杂目标拆解为子任务，动态调用工具并反思优化，实现从&quot;被动应答&quot;到&quot;主动解决问题&quot;的跨越。工程上永远先问一句：这个任务能不能用直接调用或固定工作流解决？Agent 应该是最后的手段，而不是第一选择。</p></blockquote><h4 id="拓展追问" tabindex="-1"><a class="header-anchor" href="#拓展追问"><span>拓展追问</span></a></h4><ol><li>Agent 循环为什么必须把工具执行结果注入回上下文？不注入会怎样？<br> 因为 LLM 无法&quot;感知&quot;外部世界，工具结果是它获得环境反馈的唯一通道。不注入 Observation，循环退化为自说自话，模型只能凭先验知识编造工具结果，这是幻觉的常见来源之一。</li><li>什么情况下 Agent 模式的成功率反而低于单次 API 调用？<br> 任务路径封闭可枚举时。Agent 的每个自主决策点都是一次出错机会，错误概率随步数复合放大——单步准确率 95% 的决策链，走 5 步后整体准确率只剩约 77%。此时固定工作流或单次调用成功率更高、成本更低。</li><li>新需求来了，如何在 Agent、工作流、直接 API 调用之间做决策？<br> 三问定位法：① 路径能否预先枚举（能→工作流）；② 是否需要外部数据或操作（不需要→直接调用即可）；③ 业务能否容忍非确定性（金融、审批等高一致场景慎用 Agent）。原则是&quot;能约束就约束，不得不自主才自主&quot;，即使用 Agent 也要配最大迭代次数、工具白名单等护栏。</li></ol><h4 id="场景题" tabindex="-1"><a class="header-anchor" href="#场景题"><span>场景题</span></a></h4><p>你的团队开发了一个&quot;保险报价 Agent&quot;：接收用户信息后自主查询费率表、计算保费并输出报价。上线后用户反馈：同样的问题每次报价都不一样，偶尔保费偏差超过 30%。你如何系统性排查和解决？</p><p><strong>参考答案</strong>：</p><ul><li><strong>应急处理</strong>：先把报价链路降级为&quot;Agent 收集信息 + 规则引擎计算&quot;，止损错误报价；同时用 Trace 平台回放线上会话，筛出报价差异明显的 Case。</li><li><strong>根因分析</strong>：通常是两层问题叠加——① 路径非确定性：Agent 每次收集信息的顺序和完整度不同，漏问关键字段（如免赔额、投保年限），导致进入计算的参数就不一样；② 数值计算交给了 LLM：让模型&quot;心算&quot;乘法和折扣，Token 生成本身就容易算错。通过 Trace 逐步比对每次调用费率工具的入参即可定位是哪一层的问题。</li><li><strong>长期方案</strong>：按&quot;Agent 管理解、确定性组件管计算&quot;重构——信息收集保留 Agent 循环但加必填字段清单（收齐才放行）；所有数值计算改为工具调用；报价结果附带来源追溯（费率表版本号 + 参数快照），使差异可复现、可审计。</li><li><strong>权衡</strong>：全流程工作流化成功率最高，但会失去多轮交互的灵活性，因此只在收集环节保留 Agent；核心原则是把非确定性放在出错代价最小的环节。</li></ul><h3 id="【中等】ai-agent-的核心架构有哪些组成部分-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】ai-agent-的核心架构有哪些组成部分-⭐⭐⭐"><span>【中等】AI Agent 的核心架构有哪些组成部分？⭐⭐⭐</span></a></h3><p>AI Agent 遵循&quot;<strong>感知-规划-行动-反思</strong>&quot;的闭环设计，由四大核心模块构成：</p><ul><li><strong>感知模块（感官）</strong>：接收用户指令和外部环境信息，支持文本、语音、图像等多模态输入。</li><li><strong>推理与决策模块（大脑）</strong>：由 LLM 驱动，通过 <code>System Prompt</code> 定义角色和约束，使用 CoT、ReAct 等策略进行任务分解与决策。</li><li><strong>执行模块（手脚）</strong>：通过 <code>Function Calling</code> 机制调用外部工具（搜索引擎、API、代码解释器、数据库等）。</li><li><strong>记忆模块（认知存储）</strong>： <ul><li><strong>短期记忆</strong>：当前对话上下文，由 LLM 上下文窗口直接承载。</li><li><strong>长期记忆</strong>：历史经验、用户偏好，通过向量数据库/知识图谱持久化存储。</li></ul></li></ul><p><strong>常见功能</strong>：自主任务规划与分解、多轮对话上下文管理、外部工具/API 调用、代码生成与执行、文件读写与数据处理、网页搜索与信息检索、多模态理解、自我反思与错误修正、多 Agent 协作编排等。</p><blockquote><p><strong>总结</strong>：LLM Agent = LLM 核心（推理引擎）+ 提示词工程层（角色/约束/工作流）+ 工具层（Function Calling）+ 记忆层（短期上下文 + 长期向量/图谱）+ 规划层（任务分解 + 推理策略）。</p></blockquote><h3 id="【中等】市面上有哪些主流的-llm-agent-框架-各自的特点是什么-⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】市面上有哪些主流的-llm-agent-框架-各自的特点是什么-⭐⭐"><span>【中等】市面上有哪些主流的 LLM Agent 框架？各自的特点是什么？⭐⭐</span></a></h3><table><thead><tr><th style="text-align:left;">框架</th><th style="text-align:left;">核心特点</th><th style="text-align:left;">适用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>LangChain / LangGraph</strong></td><td style="text-align:left;">生态最完善，链式调用、工具集成、图形化多 Agent 工作流</td><td style="text-align:left;">复杂工作流、生产级应用</td></tr><tr><td style="text-align:left;"><strong>AutoGen（微软）</strong></td><td style="text-align:left;">轻量级消息列表记忆，侧重多 Agent 对话式协作</td><td style="text-align:left;">快速开发、多 Agent 协同</td></tr><tr><td style="text-align:left;"><strong>CrewAI</strong></td><td style="text-align:left;">角色化设计，内置多种记忆类型（短期 RAG、长期 SQLite）</td><td style="text-align:left;">分工明确的多 Agent 系统</td></tr><tr><td style="text-align:left;"><strong>Google ADK</strong></td><td style="text-align:left;">Google 官方 Agent 开发工具包，原生支持 A2A 协议</td><td style="text-align:left;">Google 生态集成</td></tr><tr><td style="text-align:left;"><strong>Spring AI</strong></td><td style="text-align:left;">Java 生态，通过 <code>@Tool</code> 注解和 <code>FunctionCallback</code> 实现工具调用</td><td style="text-align:left;">企业级 Java 应用</td></tr></tbody></table><p><strong>选型背后的权衡：控制粒度 vs 开发速度</strong></p><table><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">优势</th><th style="text-align:left;">代价与失效场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>LangGraph（显式图/状态机）</strong></td><td style="text-align:left;">状态可持久化、支持中断恢复（HITL）、每步可回放</td><td style="text-align:left;">图定义样板代码多，简单任务显得笨重</td></tr><tr><td style="text-align:left;"><strong>AutoGen/CrewAI（对话式编排）</strong></td><td style="text-align:left;">几十行代码搭起多 Agent 协作，上手极快</td><td style="text-align:left;">流程靠对话涌现难以控制，生产调试和回归困难</td></tr><tr><td style="text-align:left;"><strong>自研轻量 Agent Loop</strong></td><td style="text-align:left;">完全可控，无抽象泄漏，Prompt/重试都在自己手里</td><td style="text-align:left;">需自建 Trace、重试、持久化等基础设施，周期长</td></tr></tbody></table><p>经验数据：需要人工审批（HITL）的任务，用 LangGraph checkpoint 机制断点恢复平均 12 秒，而无状态方案需从头重跑，平均 4 分钟以上；但纯 PoC 验证阶段，CrewAI 的搭建速度可达 LangGraph 的 3~5 倍。</p><p><strong>真实踩坑案例（框架升级破坏性变更）</strong>：</p><ul><li><strong>现象</strong>：LangChain 从 0.1 升到 0.3 后，离线评测 Recall@5 从 0.86 跌到 0.61，且无任何告警。</li><li><strong>排查</strong>：二分定位到 Retriever 接口默认行为变化（返回格式从 <code>Document</code> 列表变为含元数据的新结构），兼容层把异常静默吞掉。</li><li><strong>根因</strong>：框架升级没有回归门禁，依赖了框架的隐式默认行为。</li><li><strong>修复</strong>：① 锁死依赖版本，升级走专项分支；② 为核心链路建立 200 条 Golden Set 回归测试，任何升级先跑回归再合入。此后两次大版本升级都在 CI 阶段拦住了类似问题。</li></ul><blockquote><p><strong>总结</strong>：选型关键看生态和语言栈——Python 生态首选 LangChain/LangGraph，Java 生态选 Spring AI，多 Agent 协作场景看 CrewAI/AutoGen，Google 生态用 ADK。但比框架选型更重要的是：把核心链路的评测集和版本回归抓在自己手里，框架只是执行层，评测集才是你的护城河。</p></blockquote><h4 id="拓展追问-1" tabindex="-1"><a class="header-anchor" href="#拓展追问-1"><span>拓展追问</span></a></h4><ol><li>LangGraph 为什么要把 Agent 执行建模成显式的图（状态机）？这对生产运维有什么实质好处？<br> 显式图把非确定的黑盒循环变成可枚举的状态转移：每个节点的输入输出、当前状态都可持久化和回放，天然支持断点恢复、人工介入和分支重试；出问题时能定位到&quot;哪个节点、哪个状态&quot;，而不是对着一段对话日志猜。</li><li>什么情况下引入框架反而成为负担？<br> 三种典型：① 框架抽象泄漏——出问题必须深入框架内部 Prompt 和重试逻辑才能定位；② 破坏性升级频繁，兼容成本超过自研成本；③ 框架包办了 Prompt 组装，你无法精细控制注入内容。当团队对链路控制力的需求超过对开发速度的需求时，就该考虑自研轻量 Loop。</li><li>一个 5 人 Java 团队要在 3 个月内交付企业内部知识 Agent，如何选型？<br> 优先 Spring AI（或 LangChain4j）：与现有 Spring Boot 服务、权限体系、监控体系同栈，工具接入复用已有 Bean；用固定工作流 + 少量 Agent 循环的混合架构控制风险；不追多 Agent 等时髦特性，把预算留给评测集和可观测建设。</li></ol><h4 id="场景题-1" tabindex="-1"><a class="header-anchor" href="#场景题-1"><span>场景题</span></a></h4><p>团队要用 Python 构建一个多 Agent 代码审查系统：代码分析 Agent → 审查意见 Agent → 人工确认 → 修复建议 Agent。要求支持人工确认环节的等待与失败步骤的重跑。你会如何选型并预防哪些坑？</p><p><strong>参考答案</strong>：</p><ul><li><strong>选型</strong>：首选 LangGraph——人工确认环节需要&quot;中断 + 状态持久化 + 恢复&quot;，这正是图状态机 + checkpointer 的强项；AutoGen/CrewAI 的对话式编排难以可靠地暂停等待人工输入。</li><li><strong>根因预防</strong>：① 每个 Agent 节点定义清晰的输入输出 Schema，避免自由文本传递导致信息失真；② 人工确认结果也作为状态写入，保证审计可追溯；③ 失败重试要幂等——审查意见生成可以重跑，但&quot;提交评论到代码仓库&quot;这类副作用操作必须去重。</li><li><strong>长期方案</strong>：核心链路建 Golden Set（50~100 个历史 MR + 人工标注的应发现缺陷），每次 Prompt/模型/框架变更都跑回归；接入 Langfuse/LangSmith 记录全链路 Trace。</li><li><strong>权衡</strong>：LangGraph 样板代码多、上手慢，PoC 阶段可先用 CrewAI 验证协作模式可行性，但生产版本必须切到可控编排——&quot;用快框架验证想法，用稳框架交付系统&quot;。</li></ul><h3 id="【中等】什么是-rag-检索增强生成-它在-agent-中扮演什么角色-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】什么是-rag-检索增强生成-它在-agent-中扮演什么角色-⭐⭐⭐⭐"><span>【中等】什么是 RAG（检索增强生成）？它在 Agent 中扮演什么角色？⭐⭐⭐⭐</span></a></h3><p><strong>RAG（Retrieval-Augmented Generation）</strong> 是一种将<strong>外部知识检索</strong>与<strong>LLM 生成</strong>相结合的技术范式：先从知识库中检索与问题相关的文档片段，再将检索结果作为上下文注入 Prompt，引导 LLM 基于真实数据生成回答。</p><p><strong>RAG 的核心流程</strong>：</p><ol><li><strong>索引阶段</strong>：将文档切分为 Chunk，通过 Embedding 模型转为向量，存入向量数据库。</li><li><strong>检索阶段</strong>：用户提问时，将问题向量化，通过语义相似度检索 Top-K 相关片段。</li><li><strong>生成阶段</strong>：将检索结果 + 用户问题一起注入 LLM，生成基于事实的回答。</li></ol><p><strong>方案权衡：RAG vs 微调 vs 长上下文</strong></p><table><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">优势</th><th style="text-align:left;">代价与失效场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>RAG</strong></td><td style="text-align:left;">知识可实时更新、可溯源、成本可控</td><td style="text-align:left;">检索失败时生成质量崩塌；需要维护索引管线</td></tr><tr><td style="text-align:left;"><strong>微调</strong></td><td style="text-align:left;">风格/格式内化好，推理时无检索开销</td><td style="text-align:left;">知识更新需重训、无法溯源、有灾难性遗忘风险</td></tr><tr><td style="text-align:left;"><strong>长上下文</strong></td><td style="text-align:left;">无需切块检索，直接塞全文</td><td style="text-align:left;">成本随长度线性涨，且存在 Lost in the Middle 注意力衰减</td></tr></tbody></table><p>选型边界：知识频繁更新、需要引用溯源→RAG；风格/格式/领域语感→微调；文档量小（&lt; 10 万字）且查询低频→长上下文直塞更简单。</p><p><strong>RAG 在 Agent 中的角色</strong>：</p><ul><li><strong>知识增强</strong>：为 Agent 提供领域专有知识，弥补 LLM 训练数据的局限性。</li><li><strong>减少幻觉</strong>：回答基于检索到的真实文档，而非 LLM 凭空生成。</li><li><strong>工具集成</strong>：RAG 本身可作为 Agent 的一个工具（如&quot;知识库查询工具&quot;），Agent 在推理链中按需调用；相比固化在管线里，工具化的 RAG 让 Agent 自主决定&quot;要不要查、查什么、查几次&quot;。</li></ul><p><strong>真实踩坑案例（检索不相关时幻觉被放大）</strong>：</p><ul><li><strong>现象</strong>：客服知识库 RAG 上线后，用户问&quot;退款失败怎么办&quot;，Agent 自信地给出了一套操作步骤，但全是错的，引发投诉。</li><li><strong>排查</strong>：回放发现 Top-1 命中的是&quot;退款成功流程&quot;文档，相似度 0.81 但语义极性相反；模型基于不相关上下文&quot;硬答&quot;，编造了具体步骤。</li><li><strong>根因</strong>：Embedding 模型对肯定/否定极性不敏感，且系统没有拒答机制——检索到什么就基于什么答，检索失败时幻觉比不检索更加危险（错误答案带着&quot;权威感&quot;）。</li><li><strong>修复</strong>：① 换用 BGE-M3 并加查询指令前缀；② 增加拒答阈值——Rerank 后 Top-1 分数 &lt; 0.35 时走转人工/拒答分支。同类问题幻觉投诉从 11% 降到 2%。</li></ul><blockquote><p><strong>总结</strong>：RAG = 检索（给 LLM 提供真实上下文）+ 生成（基于上下文产出精准回答），是 Agent 连接私有知识库、减少幻觉的核心桥梁。但要记住：RAG 只能把幻觉从&quot;无据编造&quot;转为&quot;有据可依&quot;，前提是检索真的召回了——检索失败时的&quot;硬答&quot;比直接说不知道危害更大，必须配套拒答机制。</p></blockquote><h4 id="拓展追问-2" tabindex="-1"><a class="header-anchor" href="#拓展追问-2"><span>拓展追问</span></a></h4><ol><li>RAG、微调、长上下文三者的能力边界到底在哪？能否互相替代？<br> 不完全可替代：RAG 解决&quot;事实性知识的注入与更新&quot;，微调解决&quot;行为模式与风格的内化&quot;，长上下文只是&quot;上下文窗口的物理扩展&quot;。实践中常见组合是 RAG 提供事实 + 微调对齐风格；知识每天变的场景微调基本出局，因为重训成本追不上更新频率。</li><li>检索结果不相关时，为什么模型&quot;硬答&quot;比拒答危害更大？架构上怎么设计兜底？<br> 因为基于错误上下文的生成带着&quot;有据可依&quot;的自信，用户无法分辨，而拒答至少把问题暴露出来。架构兜底：① 检索侧设相关性阈值（Rerank 分数），低于阈值不注入；② 生成侧要求引用来源，无引用则拒答；③ 低置信查询路由到人工。三道闸门的成本远低于一次错误回答的事故成本。</li><li>RAG 作为 Agent 工具与固化在管线里，两种形态怎么选？<br> 固定问答场景（知识库机器人）固化管线更可控：每次必检索，质量稳定可评测；开放任务 Agent 则应工具化，让 Agent 自己决定何时检索、检索什么，避免无谓检索引入噪声。代价是工具化后行为非确定，需要额外的调用日志和评测覆盖。</li></ol><h4 id="场景题-2" tabindex="-1"><a class="header-anchor" href="#场景题-2"><span>场景题</span></a></h4><p>公司要把 3000 份 PDF 产品说明书变成&quot;智能问答&quot;，预算有限、要求 6 周上线。请给出 MVP 方案设计，并指出最先要预防的三个坑。</p><p><strong>参考答案</strong>：</p><ul><li><strong>MVP 架构</strong>：PDF 解析（优先保留标题层级和表格）→ 结构感知分块（256~512 Token）→ BGE 类中文 Embedding + 向量库（如 Elasticsearch/Milvus）→ BM25 + 向量混合召回 + 开源 Reranker → 生成时强制引用来源；先用固定管线而非 Agent，控制复杂度。</li><li><strong>最先预防的三个坑</strong>：① PDF 解析坑——双栏、页眉页脚、表格解析错乱是最大脏数据源，上线前抽 50 份人工目检解析结果；② 分块坑——表格/步骤列表被拦腰切断，需结构感知 + 小块检索大块返回；③ 拒答坑——知识库里没有的问题必须有拒答分支，否则模型会基于相似但不相关的文档编造，这是用户信任的头号杀手。</li><li><strong>验证方式</strong>：上线前用真实用户问题（从客服工单抽样 100 条）建评测集，跑 Recall@5、faithfulness、答案相关性三个指标，设定上线门槛（如 Recall@5 ≥ 0.85）。</li><li><strong>权衡</strong>：6 周预算下不上 GraphRAG、不自训 Embedding、不做多模态（图表图片先丢），把力气花在解析质量和拒答兜底上——这两个决定了用户的第一印象。</li></ul><h2 id="rag-深度" tabindex="-1"><a class="header-anchor" href="#rag-深度"><span>RAG 深度</span></a></h2><h3 id="【中等】rag-的分块策略-chunking-有哪些-如何选择合适的分块方式-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】rag-的分块策略-chunking-有哪些-如何选择合适的分块方式-⭐⭐⭐⭐"><span>【中等】RAG 的分块策略（Chunking）有哪些？如何选择合适的分块方式？⭐⭐⭐⭐</span></a></h3><p>分块（Chunking）是 RAG 索引阶段的核心环节，直接影响检索召回质量。常见策略：</p><table><thead><tr><th style="text-align:left;">策略</th><th style="text-align:left;">原理</th><th style="text-align:left;">适用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>固定大小分块</strong></td><td style="text-align:left;">按固定 Token 数切分，相邻块保留重叠（Overlap）</td><td style="text-align:left;">快速落地，通用文档</td></tr><tr><td style="text-align:left;"><strong>语义分块</strong></td><td style="text-align:left;">按 Embedding 相似度变化点切分，保持语义完整</td><td style="text-align:left;">段落语义差异大的文档</td></tr><tr><td style="text-align:left;"><strong>结构感知分块</strong></td><td style="text-align:left;">按 Markdown 标题、HTML 标签等文档结构切分</td><td style="text-align:left;">技术文档、Wiki、法规条款</td></tr><tr><td style="text-align:left;"><strong>递归分块</strong></td><td style="text-align:left;">按分隔符优先级（段落→句子→词）递归切分</td><td style="text-align:left;">LangChain 默认策略，较通用</td></tr><tr><td style="text-align:left;"><strong>父子分块/小块检索</strong></td><td style="text-align:left;">用小块做检索匹配，命中后返回所属大块上下文</td><td style="text-align:left;">兼顾检索精度与上下文完整性</td></tr></tbody></table><p><strong>方案权衡：固定分块 vs 语义分块 vs 结构感知</strong></p><table><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">优势</th><th style="text-align:left;">失效场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>固定大小分块</strong></td><td style="text-align:left;">实现简单、行为可预测</td><td style="text-align:left;">无视语义边界，表格/列表/跨段论述是天然受害者</td></tr><tr><td style="text-align:left;"><strong>语义分块</strong></td><td style="text-align:left;">语义完整性好</td><td style="text-align:left;">依赖 Embedding 质量；语义均匀的长文（如法律条文）找不到明显断点，反而切得更碎</td></tr><tr><td style="text-align:left;"><strong>结构感知分块</strong></td><td style="text-align:left;">利用文档自身结构，可解释</td><td style="text-align:left;">依赖解析质量，无结构文档（纯扫描件 OCR）无法使用</td></tr></tbody></table><p><strong>选择要点</strong>：</p><ol><li><strong>块大小权衡</strong>：太小（&lt;128 Token）语义碎片化，太大（&gt;1024 Token）检索精度下降，经验区间 <strong>200~500 Token 起步</strong>（256~512 最常用）。</li><li><strong>重叠设置</strong>：Overlap 一般取块大小的 <strong>10%~20%</strong>，避免关键信息被切断在边界。</li><li><strong>元数据增强</strong>：为每个 Chunk 附加标题、章节路径等元数据，检索时一并参与匹配（即&quot;上下文丰富化&quot;，如 LlamaIndex 的 Sentence Window 和 Auto-Merging）。</li></ol><p><strong>真实踩坑案例（512 Token 切断表格）</strong>：</p><ul><li><strong>现象</strong>：财报问答中用户问&quot;去年各子公司经营性现金流&quot;，回答总缺某个子公司的列，且数字张冠李戴。</li><li><strong>排查</strong>：回放检索发现该表格被 512 Token 固定分块切成 3 块，表头与表体分属不同 Chunk，模型不知道每行数字对应哪列。</li><li><strong>根因</strong>：固定分块不感知文档结构，表格、代码块、有序列表这类&quot;结构内聚单元&quot;是天然受害者。</li><li><strong>修复</strong>：改为结构感知分块（表格整体保留，超长时连同表头一起切分）+ 小块检索大块返回；相关问题的 Recall@5 从 43% 提升到 91%。</li></ul><blockquote><p><strong>总结</strong>：分块的本质是&quot;检索粒度与语义完整性的博弈&quot;——没有万能参数，应基于评估集（召回率指标）针对不同文档类型实验调优。经验起点：256~512 Token + 10%~20% overlap，有结构的文档优先结构感知，表格密集场景务必整表保留。</p></blockquote><h4 id="拓展追问-3" tabindex="-1"><a class="header-anchor" href="#拓展追问-3"><span>拓展追问</span></a></h4><ol><li>块大小如何影响&quot;召回精度 vs 上下文完整性&quot;的权衡？为什么 200~500 Token 是常见经验区间？<br> 块越小，向量表达越聚焦，检索精度越高，但单块承载不了完整论述，答案所需信息可能散落多块；块越大上下文越完整，但向量被多种语义稀释，相似度信号变弱。200~500 Token 大致是&quot;一个完整论点/段落&quot;的长度，且主流 Embedding 模型（512 Token 窗口）在这个区间编码质量最佳。</li><li>语义分块的&quot;语义断点&quot;是怎么判定的？什么文档上它反而更差？<br> 典型做法是对相邻句子计算 Embedding 相似度，相似度跌破阈值（或出现局部谷值）处切分。失效于语义均匀的长文：法律条文、流水式会议记录全文相似度都很高，找不到断点，退化为按最大长度硬切，甚至因阈值扰动切得更碎。</li><li>生产中调整分块策略，如何安全上线并防止回归？<br> 分块变更会重建整个索引，必须灰度：① 固定评测集（真实问题 + 标注命中文档）；② 新旧索引并行跑 Recall@K/MRR 对比，新策略不劣于旧策略才切流；③ 保留旧索引可回滚。切忌&quot;改了参数直接重建上线&quot;，分块效果的回归往往是静默的。</li></ol><h4 id="场景题-3" tabindex="-1"><a class="header-anchor" href="#场景题-3"><span>场景题</span></a></h4><p>企业知识库中有一批法律合同模板：条款互相引用（&quot;按第 5.2 条执行&quot;）、单条款很长、用户提问经常跨条款。如何设计分块与检索方案？</p><p><strong>参考答案</strong>：</p><ul><li><strong>应急/验证</strong>：先抽 50 个真实用户问题标注应命中的条款，建评测集，避免凭感觉调参。</li><li><strong>分块设计</strong>：结构感知分块，以&quot;条款（如 5.2）&quot;为最小单元而非固定 Token；超长条款内部再按句切分但保留条款号元数据；跨条款引用（&quot;按第 5.2 条执行&quot;）在索引时把被引用条款一并追加到当前 Chunk 的上下文中（引用展开）。</li><li><strong>检索设计</strong>：小块（句子级）检索 + 大块（整条款）返回的父子分块；对包含条款号的查询走 BM25 精确匹配（&quot;5.2&quot;这类编号向量检索基本召不回）。</li><li><strong>权衡</strong>：引用展开会增大索引体积和构建时间，但法律场景错误答案的代价极高，值得；全局性问题（&quot;这份合同的整体风险&quot;）不适合逐块检索，可预生成合同级摘要单独索引。</li><li><strong>量化验证</strong>：目标 Recall@5 ≥ 0.9（法律场景门槛应高于一般知识库），上线后持续监控未命中查询占比。</li></ul><h3 id="【中等】rag-中的混合检索-hybrid-search-和重排序-rerank-是什么-为什么需要它们-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】rag-中的混合检索-hybrid-search-和重排序-rerank-是什么-为什么需要它们-⭐⭐⭐⭐"><span>【中等】RAG 中的混合检索（Hybrid Search）和重排序（Rerank）是什么？为什么需要它们？⭐⭐⭐⭐</span></a></h3><p><strong>混合检索</strong>是同时使用多种检索方式并融合结果的策略：</p><table><thead><tr><th style="text-align:left;">检索方式</th><th style="text-align:left;">优势</th><th style="text-align:left;">劣势</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>向量检索（稠密）</strong></td><td style="text-align:left;">语义理解强，能匹配同义改写</td><td style="text-align:left;">对精确关键词、编号、代码不敏感</td></tr><tr><td style="text-align:left;"><strong>关键词检索（稀疏，如 BM25）</strong></td><td style="text-align:left;">精确匹配专有名词、数字、错误码</td><td style="text-align:left;">无法理解语义相似</td></tr></tbody></table><p>混合检索通常用 <strong>RRF（Reciprocal Rank Fusion）</strong> 或加权分数归一化融合两路结果，兼得语义召回与精确匹配。</p><p><strong>方案权衡：纯向量检索 vs 混合检索</strong></p><table><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">适用边界</th><th style="text-align:left;">失效场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>纯向量</strong></td><td style="text-align:left;">查询以自然语言为主、无精确标识符的通用问答</td><td style="text-align:left;">错误码/单号/型号/生僻专有名词查询召回崩塌</td></tr><tr><td style="text-align:left;"><strong>混合检索</strong></td><td style="text-align:left;">查询中混合语义描述与精确标识符（企业知识库常态）</td><td style="text-align:left;">多一路索引的存储与运维成本；融合权重需调优</td></tr></tbody></table><p><strong>重排序（Rerank）</strong>：第一阶段检索召回 Top-K（如 50 条）候选后，用 Cross-Encoder 重排模型（如 BGE-Reranker、Cohere Rerank）对&quot;查询-文档&quot;逐对精细打分，重新排序后取 Top-N（如 5 条）注入 Prompt。</p><p><strong>为什么需要 Rerank</strong>：</p><ul><li>向量检索用 Bi-Encoder（查询与文档独立编码），速度快但打分粗糙；Cross-Encoder 联合编码精度高但慢，只适合小候选集精排。</li><li>两段式架构（粗排 + 精排）能在延迟可控的前提下显著提升最终注入上下文的相关性，直接提升回答质量。</li><li>量化收益参考：在内部知识库评测中，仅向量检索 MRR@5 约 0.52，加 BM25 + RRF 后升至 0.63，再叠加 Cross-Encoder 重排后达 0.71（<strong>相对提升约 37%</strong>）；P95 延迟增加约 380ms，在可接受范围内。</li></ul><p><strong>真实踩坑案例（错误码查询召回失灵）</strong>：</p><ul><li><strong>现象</strong>：运维知识库问答中，用户问&quot;ERROR-4012 数据库连接超时&quot;，回答总是泛泛的排查思路，无法给出针对性方案。</li><li><strong>排查</strong>：回放发现专门讲解 4012 的文档排在第 7 位未进 Top-5，而 Top-1 是一篇泛泛的&quot;超时问题概览&quot;——两篇向量相似度只差 0.03。</li><li><strong>根因</strong>：Embedding 对数字/代码类精确标识符不敏感，&quot;4012&quot;在向量空间里几乎没有区分度。</li><li><strong>修复</strong>：增加 BM25 路并用 RRF 融合（k=60），4012 文档升到 Top-1；叠加 rerank 后同类问题回答满意度从 58% 升至 86%。</li></ul><blockquote><p><strong>总结</strong>：混合检索解决&quot;召回全不全&quot;，Rerank 解决&quot;排序准不准&quot;——&quot;BM25 + 向量混合召回 + Cross-Encoder 精排&quot;是 2025 年生产级 RAG 的标准配置。失效边界：查询极短（1~2 词）时两路信号都弱，rerank 也难救；此时更应做查询改写/扩展。</p></blockquote><h4 id="拓展追问-4" tabindex="-1"><a class="header-anchor" href="#拓展追问-4"><span>拓展追问</span></a></h4><ol><li>RRF 融合的原理是什么？为什么不直接对两路分数归一化后加权求和？<br> RRF 只用排名不用分数：score(d) = Σ 1/(k + rank_i(d))，k 通常取 60。直接加权分数的问题是 BM25 分数无上界、向量相似度有界，两者分布形态完全不同，归一化对离群值敏感且跨查询不稳定；RRF 免调参、鲁棒，是默认首选。</li><li>为什么不直接用 Cross-Encoder 做一阶检索？召回 K 和精排 N 怎么定？<br> Cross-Encoder 需要对每个文档与查询联合前向传播，无法预计算索引，全库扫描延迟不可接受（万级文档就是万级推理）。经验参数：K 取 50~100（保证目标文档在候选内，可用 Recall@K 验证），N 取 3~8（受注入 Token 预算约束）；K 太小精排无米下锅，N 太大注入噪声且涨延迟。</li><li>Rerank 模型超时或宕机时如何降级？对尾延迟有什么影响？<br> Rerank 是同步串行环节，直接叠加在 P99 上，必须设超时（如 500ms）和降级开关：超时后回退为按混合检索分数排序取 Top-N，宁肯排序粗一点也不阻塞主链路。同时要监控&quot;降级率&quot;，若长期 &gt; 1% 说明 rerank 服务容量不足，需扩容而非一直裸奔。</li></ol><h4 id="场景题-4" tabindex="-1"><a class="header-anchor" href="#场景题-4"><span>场景题</span></a></h4><p>企业 RAG 上线后运营反馈：&quot;常见问题回答很准，但长尾专有名词（产品型号、客户编号、内部术语）几乎全错。&quot;你如何排查并优化检索链路？</p><p><strong>参考答案</strong>：</p><ul><li><strong>应急处理</strong>：收集 30~50 个错误 Case，按查询类型分类（型号/编号/术语/普通语义），先确认错误集中在哪类；对已知错误查询可临时加入查询改写规则止损。</li><li><strong>根因分析</strong>：逐 Case 回放检索：若目标文档在索引中但排名靠后→召回问题（向量对精确标识符不敏感）；若根本不在索引→分块/解析问题。长尾专有名词错误大概率是前者：单路向量检索的固有盲区。</li><li><strong>长期方案</strong>：① 加 BM25 混合检索 + RRF 融合；② 叠加 rerank 提升排序精度；③ 对编号类查询加查询分类，直接走精确匹配路径；④ 用这批 Bad Case 建评测集，量化改造前后 MRR@5 变化。</li><li><strong>权衡</strong>：全链路改造需重建索引、增加运维复杂度；若 Bad Case 只集中在极少数模式（如纯编号查询），用一条查询路由规则（正则识别编号→走 BM25）成本远低于全量混合检索改造——先用最小代价方案验证收益，再决定要不要全量铺开。</li></ul><h3 id="【困难】rag-系统如何评估-有哪些核心指标-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】rag-系统如何评估-有哪些核心指标-⭐⭐⭐⭐"><span>【困难】RAG 系统如何评估？有哪些核心指标？⭐⭐⭐⭐</span></a></h3><p>RAG 评估需拆解为<strong>检索质量</strong>和<strong>生成质量</strong>两个环节分别度量：</p><p><strong>检索侧指标</strong>：</p><table><thead><tr><th style="text-align:left;">指标</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>召回率（Recall@K）</strong></td><td style="text-align:left;">相关文档被检索进 Top-K 的比例</td></tr><tr><td style="text-align:left;"><strong>精确率（Precision@K）</strong></td><td style="text-align:left;">Top-K 中相关文档的占比</td></tr><tr><td style="text-align:left;"><strong>MRR / NDCG</strong></td><td style="text-align:left;">相关文档排序位置的质量</td></tr><tr><td style="text-align:left;"><strong>上下文相关性（Context Relevance）</strong></td><td style="text-align:left;">检索片段与问题的相关程度</td></tr></tbody></table><p><strong>生成侧指标</strong>：</p><table><thead><tr><th style="text-align:left;">指标</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>忠实度（Faithfulness）</strong></td><td style="text-align:left;">回答是否忠于检索到的上下文，不编造（防幻觉）</td></tr><tr><td style="text-align:left;"><strong>答案相关性（Answer Relevance）</strong></td><td style="text-align:left;">回答与用户问题的匹配程度</td></tr><tr><td style="text-align:left;"><strong>答案正确性</strong></td><td style="text-align:left;">与标准答案（Ground Truth）的一致性</td></tr></tbody></table><p><strong>主流评估框架</strong>：</p><ul><li><strong>RAGAS</strong>：最流行的 RAG 评估框架，内置 Faithfulness、Context Relevance 等指标，支持 LLM-as-a-Judge 自动评分。</li><li><strong>TruLens</strong>：提供 RAG Triad（上下文相关性、答案接地性、答案相关性）评估和可观测追踪。</li><li><strong>DeepEval</strong>：通用 LLM 评估框架，支持 RAG 指标和自定义断言。</li></ul><p><strong>方案权衡：自动评估（LLM-as-a-Judge）vs 人工评估</strong></p><table><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">优势</th><th style="text-align:left;">代价与失效场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>LLM-as-a-Judge</strong></td><td style="text-align:left;">可规模化、可回归、成本可控</td><td style="text-align:left;">偏爱长答案、偏袒同源模型；与真实体验可能脱节</td></tr><tr><td style="text-align:left;"><strong>人工评估</strong></td><td style="text-align:left;">金标准，能捕捉体验类问题</td><td style="text-align:left;">贵且慢，无法每次变更都跑；标注者间一致性需控制</td></tr></tbody></table><p>实践姿势：日常迭代用自动评估做门禁，定期（如双周）抽样人工校准，监控两者一致性；经验上生产 RAG 的 faithfulness 应 ≥ 0.85，低于此线不建议放量。</p><p><strong>真实踩坑案例（指标好看但用户不买账）</strong>：</p><ul><li><strong>现象</strong>：RAGAS faithfulness 评到 0.92，但线上用户点踩率仍有 15%。</li><li><strong>排查</strong>：人工抽查 100 条点踩 Case，发现大多是&quot;回答忠实但完全没答到点上&quot;——评测集的问题是开发者自己编的，与真实用户问题分布严重偏离。</li><li><strong>根因</strong>：评测集分布偏差 + 只测了 faithfulness 没测 answer relevance，指标优化方向与用户体验脱节。</li><li><strong>修复</strong>：从线上真实日志分层抽样 200+ 问题重建评测集，并增加 answer relevance 门禁（≥ 0.8）；调整后离线指标与点踩率的相关性从弱相关变为显著（点踩率降至 6%）。</li></ul><blockquote><p><strong>总结</strong>：RAG 评估的关键是&quot;分段归因&quot;——回答差先判断是检索没召回（优化分块/混合检索）还是生成没用好（优化 Prompt/Rerank），用 RAGAS 等框架建立指标基线后才能数据驱动地调优。但永远记住：评测集的分布比指标算法更重要，指标必须定期与真实用户反馈对齐。</p></blockquote><h4 id="拓展追问-5" tabindex="-1"><a class="header-anchor" href="#拓展追问-5"><span>拓展追问</span></a></h4><ol><li>RAGAS 的 faithfulness 是怎么计算的？为什么它和人工判断有时不一致？<br> RAGAS 先把答案拆成原子声明（claims），再逐条判断能否被检索上下文支撑，得分 = 被支撑声明占比。与人工不一致的原因：① 拆分粒度影响结果，模糊表述可能被误判为&quot;可支撑&quot;；② 它只查&quot;有无依据&quot;不查&quot;依据本身对不对&quot;——检索到的文档本身过时/错误时，faithfulness 照样满分。</li><li>LLM-as-a-Judge 有哪些已知偏差？怎么缓解？<br> 已知偏差：偏爱长答案、偏袒同家族模型的输出、对格式敏感（列表/加粗易得高分）。缓解：① 归一化长度后评估或用长度受控的参考答案；② 用与被评系统不同家族的模型当裁判；③ 定期用人工标注样本校准裁判，一致性（如 Cohen&#39;s Kappa）低于 0.6 就换裁判方案。</li><li>没有标准答案的开放问题（如&quot;总结这份报告&quot;）如何构造 Ground Truth？<br> 三种替代：① 用 rubric（评分细则）代替标准答案，人工/裁判按维度打分；② 构造&quot;必要事实清单&quot;——答案必须包含的 N 个关键事实，测覆盖率；③ 两两对比（pairwise）新旧版本输出，只判相对优劣不判绝对分，适合版本迭代回归。</li></ol><h4 id="场景题-5" tabindex="-1"><a class="header-anchor" href="#场景题-5"><span>场景题</span></a></h4><p>领导问你：&quot;上个月你们做的 RAG 优化（换了 Embedding 模型 + 加了 rerank），到底提升了多少？&quot;你如何用数据回答？如果发现当时没有提前建评测集，怎么补救？</p><p><strong>参考答案</strong>：</p><ul><li><strong>有评测集的情况</strong>：直接给出对照实验数据——同一评测集上新旧管线的 Recall@5、MRR、faithfulness、answer relevance 四个指标对比（如 Recall@5：0.72 → 0.85），再叠加线上指标（点踩率、转人工率）验证离线收益是否传导到体验，最后附成本变化（rerank 增加的延迟与费用）。</li><li><strong>没评测集的补救</strong>：① 从线上日志抽 200 条真实查询，人工标注应命中文档和参考答案（约 2~3 人天）；② 旧管线可回滚重建（保留旧版索引和配置），在新评测集上重跑旧管线得到基线；③ 若旧管线已无法复现，至少用线上历史指标（点赞率、转人工率）做前后对比，并明确标注&quot;非严格对照&quot;。</li><li><strong>长期机制</strong>：把评测集建设纳入变更门禁——任何检索/生成链路变更必须附评测报告才能上线；评测集每月从线上 Bad Case 增补，保持分布鲜活。</li><li><strong>权衡</strong>：事后补评测集的结论可信度不如事前对照实验（存在标注者被新答案锚定的风险），因此补救方案要主动说明局限性——这比硬给一个精确数字更专业。</li></ul><h3 id="【中等】什么是-graphrag-它和传统向量-rag-有什么区别-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】什么是-graphrag-它和传统向量-rag-有什么区别-⭐⭐⭐"><span>【中等】什么是 GraphRAG？它和传统向量 RAG 有什么区别？⭐⭐⭐</span></a></h3><p><strong>GraphRAG</strong>（微软 2024 年提出）是将<strong>知识图谱</strong>引入 RAG 的进阶方案：先从文档中抽取实体和关系构建图谱，检索时利用图结构进行多跳推理和全局聚合，再注入 LLM 生成回答。</p><p><strong>与传统向量 RAG 的区别</strong>：</p><table><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">向量 RAG（Naive RAG）</th><th style="text-align:left;">GraphRAG</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>知识表示</strong></td><td style="text-align:left;">离散的文本 Chunk + 向量</td><td style="text-align:left;">实体-关系图谱 + 社区聚类</td></tr><tr><td style="text-align:left;"><strong>检索能力</strong></td><td style="text-align:left;">单跳语义相似度匹配</td><td style="text-align:left;">支持多跳关系推理（A→B→C 的间接关联）</td></tr><tr><td style="text-align:left;"><strong>全局问题</strong></td><td style="text-align:left;">无法回答&quot;这批文档的整体主题&quot;类问题</td><td style="text-align:left;">通过社区摘要（Community Summary）支持全局性问题</td></tr><tr><td style="text-align:left;"><strong>构建成本</strong></td><td style="text-align:left;">低，切块 + 向量化即可</td><td style="text-align:left;">高，需 LLM 抽取实体关系，索引成本大</td></tr><tr><td style="text-align:left;"><strong>适用场景</strong></td><td style="text-align:left;">局部事实问答，文档量大而结构松散</td><td style="text-align:left;">实体关系密集的领域（金融、法律、医疗、尽调）</td></tr></tbody></table><p><strong>典型流程</strong>：文档 → LLM 抽取实体/关系 → 构建图谱 → Leiden 算法社区检测 → 为每个社区生成摘要 → 查询时选择 Local Search（实体邻域）或 Global Search（社区摘要 Map-Reduce 聚合）。</p><blockquote><p><strong>总结</strong>：GraphRAG 用&quot;关系结构&quot;弥补向量 RAG&quot;只见树木不见森林&quot;的缺陷，擅长多跳推理和全局性问题，但索引成本高——简单问答用向量 RAG，关系密集型知识才值得上 GraphRAG。</p></blockquote><h3 id="【简单】什么是-llm-的幻觉问题-agent-如何缓解幻觉-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【简单】什么是-llm-的幻觉问题-agent-如何缓解幻觉-⭐⭐⭐⭐"><span>【简单】什么是 LLM 的幻觉问题？Agent 如何缓解幻觉？⭐⭐⭐⭐</span></a></h3><p><strong>幻觉（Hallucination）</strong> 是指 LLM 生成的内容看似流畅合理，但实际上<strong>与事实不符或缺乏依据</strong>的现象。主要表现为：捏造不存在的事实、引用虚假来源、逻辑推理错误等。本题聚焦 <strong>Agent 架构层</strong>的缓解手段（提示词层面的技巧与工程检测管线属于另两个话题，此处不展开）。</p><p><strong>Agent 架构层的四道防线</strong>：</p><table><thead><tr><th style="text-align:left;">防线</th><th style="text-align:left;">机制</th><th style="text-align:left;">成本与失效场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>RAG 事实锚定</strong></td><td style="text-align:left;">检索真实文档作为上下文，强制引用来源，无引用则拒答</td><td style="text-align:left;">检索失败时幻觉被放大（&quot;硬答&quot;比拒答更危险）</td></tr><tr><td style="text-align:left;"><strong>工具调用结果校验</strong></td><td style="text-align:left;">用 API/数据库返回的真实数据替代模型记忆；对返回做 Schema 校验</td><td style="text-align:left;">工具失败后若无硬约束，模型会自由发挥</td></tr><tr><td style="text-align:left;"><strong>自我反思（Reflection/Self-Refine）</strong></td><td style="text-align:left;">生成后用评审 Prompt 检查一致性/依据，不合格则重新推理</td><td style="text-align:left;">多一轮推理延迟 +50%~100%；可能对错误结论过度自信</td></tr><tr><td style="text-align:left;"><strong>多 Agent 交叉验证</strong></td><td style="text-align:left;">多个 Agent（或多次采样）独立作答，不一致时触发仲裁</td><td style="text-align:left;">成本 3~5 倍；同基座模型可能犯相关性错误</td></tr></tbody></table><p><strong>方案权衡</strong>：反思是性价比最高的单点手段（一轮推理成本换显著降幻觉）；多 Agent 交叉验证适合金融/医疗等高风险关键路径，全量使用成本不可接受——实践中的姿势是&quot;全量 RAG 锚定 + 全量工具校验 + 高风险意图才走反思/交叉验证&quot;的分层防御。</p><p><strong>真实踩坑案例（客服事故）</strong>：</p><ul><li><strong>现象</strong>：客服 Agent 告诉用户&quot;您的情况可以无条件全额退款&quot;，引发批量投诉，用户到平台引用该承诺要求兑现。</li><li><strong>排查</strong>：Trace 回放发现 Agent 调用了退款政策工具，但工具报错（库存服务超时），Agent 没有告知错误，而是凭自己的&quot;常识&quot;给出了对用户有利的承诺。</li><li><strong>根因</strong>：工具失败缺乏硬约束——LLM 把&quot;没有结果&quot;当成&quot;可以自由回答&quot;，架构上没有拦截这一分支。</li><li><strong>修复</strong>：① 工具调用失败强制进入拒答/转人工分支，不给模型自由发挥空间；② 工具结果做 Schema 校验，生成时缺少关键字段即触发反思重试；③ 退款/赔付等高风险意图增加审核 Agent 交叉验证。政策类幻觉投诉降为零。</li></ul><blockquote><p><strong>总结</strong>：幻觉的根源是 LLM 的概率生成本质——它&quot;预测下一个 token&quot;而非&quot;查证事实&quot;。Agent 架构层的防线是：用 RAG 把生成锚定在真实文档上，用工具调用获取实时数据并硬校验结果，用反思机制自我纠错，用多 Agent 交叉验证兜住高风险路径——四道防线的共同前提是：任何一环失效都要有明确的降级路径（拒答/转人工），而不是让模型&quot;自由发挥&quot;。</p></blockquote><h4 id="拓展追问-6" tabindex="-1"><a class="header-anchor" href="#拓展追问-6"><span>拓展追问</span></a></h4><ol><li>自我反思为什么有时不仅纠错，反而&quot;强化&quot;错误？反思机制要真正生效需要什么条件？<br> 因为生成和评审用的是同一个模型，若错误源于模型的系统性偏差（如错误的先验知识），它自查时也会得出同样结论，甚至因重复生成而对错误更自信。生效条件：① 评审时提供外部依据（检索结果/工具返回值），让反思变成&quot;对照证据检查&quot;而非&quot;凭感觉自查&quot;；② 评审 Prompt 要求逐条列出依据；③ 有条件时用不同家族模型做评审。</li><li>多 Agent 交叉验证在什么情况下会失效？如何降低相关性错误？<br> 当多个 Agent 用同一基座模型、同一知识源时，错误是相关的——它们会&quot;异口同声地犯同一个错&quot;，投票毫无意义。降低相关性：① 异构基座（不同厂商模型）；② 异源知识（不同检索库/工具）；③ 不同推理路径（一个用 RAG、一个用工具查询）。代价是成本和延迟线性增长，因此只用在错误代价最高的路径上。</li><li>金融/医疗等高风险场景，校验成本与幻觉风险如何权衡？<br> 原则是&quot;按风险分级投入防御&quot;：低风险闲聊不校验；事实查询加 RAG 引用；高风险决策（用药、交易、赔付）叠加反思 + 异构交叉验证 + 人工审批。同时建立幻觉事故库，每个 Bad Case 回溯是哪道防线失效，把预算投向失效频率最高的环节，而不是全链路无差别堆防御。</li></ol><h4 id="场景题-6" tabindex="-1"><a class="header-anchor" href="#场景题-6"><span>场景题</span></a></h4><p>客服 Agent 在&quot;售后政策&quot;类问题上约 3‰ 的回答存在幻觉，已发生两起用户投诉。请给出完整的治理方案。</p><p><strong>参考答案</strong>：</p><ul><li><strong>应急处理</strong>：① 售后政策类问题临时降级为&quot;检索 FAQ 精确匹配 + 无匹配转人工&quot;，不让模型自由生成；② 把两起投诉 Case 完整回放，确认幻觉发生的具体环节。</li><li><strong>根因分析</strong>：通过 Trace 逐环节检查：检索是否召回正确政策文档（检索问题）；工具是否报错后被模型自由发挥（工具失败处理问题）；生成是否超出上下文编造细节（生成问题）。实践中往往三者叠加：召回不准 + 工具失败无拦截 + 无引用约束。</li><li><strong>长期方案</strong>（按架构四防线落地）：① RAG 锚定：政策文档高优先级索引 + 强制引用，无引用拒答；② 工具校验：政策查询工具失败即转人工，Schema 校验关键字段；③ 反思：政策类回答生成后增加一轮&quot;逐句对照文档&quot;检查；④ 交叉验证：赔付承诺等高风险输出由审核 Agent 复核。上线门槛：政策类评测集幻觉率 &lt; 0.5‰。</li><li><strong>权衡</strong>：四防线全开会显著增加延迟与成本，因此分级：普通政策咨询只开 ①②，涉及赔付承诺才开 ③④；同时接受&quot;拒答率适度上升&quot;作为代价——用户等几秒转人工，远好过拿到一个错误承诺。</li></ul><h2 id="记忆、工具与规划" tabindex="-1"><a class="header-anchor" href="#记忆、工具与规划"><span>记忆、工具与规划</span></a></h2><h3 id="【中等】ai-agent-的记忆机制有哪些类型-如何实现长短期记忆-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】ai-agent-的记忆机制有哪些类型-如何实现长短期记忆-⭐⭐⭐⭐"><span>【中等】AI Agent 的记忆机制有哪些类型？如何实现长短期记忆？⭐⭐⭐⭐</span></a></h3><p>AI Agent 的记忆分为四种类型：</p><table><thead><tr><th style="text-align:left;">记忆类型</th><th style="text-align:left;">定义</th><th style="text-align:left;">实现方案</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>工作记忆</strong></td><td style="text-align:left;">当前任务的即时上下文</td><td style="text-align:left;">LLM 上下文窗口直接承载</td></tr><tr><td style="text-align:left;"><strong>短期记忆</strong></td><td style="text-align:left;">近期对话历史和中间推理结果</td><td style="text-align:left;">向量数据库存储最近 N 轮对话的语义关联</td></tr><tr><td style="text-align:left;"><strong>长期记忆</strong></td><td style="text-align:left;">用户偏好、历史经验、领域知识</td><td style="text-align:left;">向量数据库（语义检索）+ 知识图谱（关系推理）</td></tr><tr><td style="text-align:left;"><strong>程序记忆</strong></td><td style="text-align:left;">编码化的操作流程和技能</td><td style="text-align:left;">固化为 Prompt 模板或工具调用链</td></tr></tbody></table><p><strong>方案权衡：全量上下文 vs 向量记忆检索 vs 摘要压缩</strong></p><table><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">优势</th><th style="text-align:left;">失效场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>全量塞上下文窗口</strong></td><td style="text-align:left;">零实现成本、信息无损</td><td style="text-align:left;">Token 成本线性增长；长对话 Lost in the Middle</td></tr><tr><td style="text-align:left;"><strong>向量记忆检索</strong></td><td style="text-align:left;">跨会话持久、按需取用</td><td style="text-align:left;">检索引入噪声：取回过时/矛盾记忆污染上下文</td></tr><tr><td style="text-align:left;"><strong>会话摘要压缩</strong></td><td style="text-align:left;">上下文精简、保留主线</td><td style="text-align:left;">细节丢失；摘要本身可能失真</td></tr></tbody></table><p>生产常见组合：窗口内保留近 N 轮原文 + 更早历史摘要化 + 跨会话事实提取为记忆条目（而非存原始对话）。</p><p><strong>长短期记忆的分层架构</strong>：</p><ol><li><strong>工作记忆层</strong>：当前任务信息留在上下文窗口内。</li><li><strong>短期记忆层</strong>：近期重要信息存入向量数据库，支持 10~20 轮对话的语义关联检索。</li><li><strong>长期记忆层</strong>：经验证的长期价值沉淀为知识图谱/图数据库。</li><li><strong>永久记忆层</strong>：进一步固化为可进化的用户档案。</li></ol><p><strong>主流实现方案</strong>：</p><ul><li><strong>Mem0</strong>：专为 Agent 设计的开源记忆层，采用向量数据库 + 知识图谱 + 键值数据库的混合存储架构，支持智能提取、去重、合并和冲突解决，引入时序权重衰减模拟人类遗忘机制。</li><li><strong>LangGraph</strong>：支持短期（运行时上下文）与长期记忆（向量数据库），同时提供实体记忆功能。</li><li><strong>混合检索策略</strong>：结合向量相似度检索和结构化查询，降低漏检风险。</li></ul><p><strong>关键工程步骤</strong>：① 使用 LLM 从对话中自动抽取结构化事实与偏好 → ② 存入混合存储（向量库 + 图数据库）→ ③ 检索时并行查询多种存储，通过评分层综合排序 → ④ 定期执行记忆去重、冲突解决和衰减清理。</p><p><strong>真实踩坑案例（长期记忆引入噪声）</strong>：</p><ul><li><strong>现象</strong>：个性化推荐 Agent 上线长期记忆后，用户反馈&quot;它记得的东西都是错的&quot;，推荐内容牛头不对马嘴。</li><li><strong>排查</strong>：发现用户三个月前随口说&quot;最近在学日语&quot;，被提取为持久偏好持续注入；同时&quot;不吃辣&quot;和&quot;点过麻辣小龙虾&quot;两条矛盾记忆被同时注入，导致回答自相矛盾。</li><li><strong>根因</strong>：记忆只进不管——无时间衰减、无冲突消解、无注入门槛，记忆库变成了噪声源。</li><li><strong>修复</strong>：① 引入时间权重衰减（偏好类记忆半衰期 30 天）；② 冲突检测：新旧记忆矛盾时由 LLM 仲裁保留最新；③ 注入设评分门槛（检索分低于阈值不注入）。记忆相关点踩下降 70%。</li></ul><blockquote><p><strong>总结</strong>：记忆系统的核心思想是分层——当前信息留窗口、近期信息存向量、长期价值沉淀图谱，通过混合检索策略在相关性和开销之间取得平衡。但要警惕：记忆不是越多越好，没有衰减、冲突消解和注入门槛的记忆系统，最终会变成污染上下文的噪声源。</p></blockquote><h4 id="拓展追问-7" tabindex="-1"><a class="header-anchor" href="#拓展追问-7"><span>拓展追问</span></a></h4><ol><li>&quot;把全量历史塞进上下文窗口&quot;和真正的记忆系统有什么本质区别？<br> 全量塞窗口是被动的、无选择的：所有信息平权占据注意力，成本随会话长度线性增长，且模型对中段信息注意力衰减。真正的记忆系统包含&quot;写入筛选（提取什么）+ 存储组织（怎么存）+ 检索注入门槛（什么时候用）&quot;三个主动决策，本质是把无限历史压缩为高密度、可检索的事实。</li><li>长期记忆什么时候会从助力变成&quot;毒源&quot;？注入门槛怎么设计？<br> 三种典型失效：① 过时记忆（用户偏好已变但旧偏好仍注入）；② 矛盾记忆同时注入导致回答自相矛盾；③ 低相关记忆挤占上下文预算，稀释真正重要的信息。门槛设计：检索相似度阈值 + 时间衰减加权 + 冲突检测三道闸，宁可不注入也不注入可疑记忆。</li><li>Mem0、Zep 这类专用记忆层和自建方案怎么选？<br> 选型看三点：① 是否需要自定义记忆 Schema 与业务实体绑定（需要→自建或深度定制）；② 数据合规（用户记忆必须私有化部署时，优先支持自托管的方案）；③ 记忆治理能力（去重、冲突解决、衰减是否内置）。起步阶段用成熟方案验证价值，记忆成为核心竞争力后再考虑自建。</li></ol><h4 id="场景题-7" tabindex="-1"><a class="header-anchor" href="#场景题-7"><span>场景题</span></a></h4><p>你要构建一个&quot;个人助理 Agent&quot;，要求跨会话记住用户习惯（如&quot;我不喝咖啡&quot;&quot;周报用表格格式&quot;）。请设计记忆架构，并说明用什么指标衡量记忆质量。</p><p><strong>参考答案</strong>：</p><ul><li><strong>架构设计</strong>：三层——① 会话内：近 10 轮原文留窗口，更早历史摘要化；② 记忆写入：每轮结束后由小模型抽取&quot;稳定事实/偏好&quot;候选（过滤掉临时性表述），经去重/冲突检测后写入；③ 记忆读取：新会话开始时不预加载，而是按当前查询语义检索相关记忆，评分达标才注入。</li><li><strong>记忆分类存储</strong>：稳定偏好（&quot;不喝咖啡&quot;）存结构化键值 + 长半衰期；一次性上下文（&quot;今天开会用中文&quot;）只留会话级；事实关系（用户所在团队/项目）存图谱便于查询。</li><li><strong>质量指标</strong>：① 记忆准确率（抽样人工核查抽取出事实的正确率，目标 ≥ 95%）；② 记忆命中率（用户提及过的偏好在后续会话中被正确使用的比例）；③ 矛盾记忆率（冲突检测告警数/记忆总数）；④ 体验指标：用户纠正&quot;你记错了&quot;的频率。</li><li><strong>权衡</strong>：写入时多花一次小模型抽取的成本，换来存储干净与检索精准；宁缺毋滥——漏记一条偏好只是体验瑕疵，记错一条偏好会持续污染所有后续会话。</li></ul><h3 id="【中等】什么是-ai-agent-中的工具调用-tool-calling-它的基本流程是怎样的-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】什么是-ai-agent-中的工具调用-tool-calling-它的基本流程是怎样的-⭐⭐⭐"><span>【中等】什么是 AI Agent 中的工具调用（Tool Calling）？它的基本流程是怎样的？⭐⭐⭐</span></a></h3><p><strong>Tool Calling</strong> 是 AI Agent 的核心能力，允许 LLM 在需要时调用外部工具/函数来获取实时数据或执行操作。LLM 本身不执行工具，而是<strong>表达调用意图</strong>，由应用程序代为执行并返回结果。</p><p><strong>基本流程</strong>：</p><ol><li><strong>定义工具</strong>：声明工具的名称、描述和参数 Schema（JSON Schema）。</li><li><strong>AI 决策</strong>：模型分析用户意图，判断是否需要调用工具，生成结构化的工具调用请求。</li><li><strong>执行工具</strong>：应用程序分发并执行对应的工具方法。</li><li><strong>结果返回</strong>：将工具执行结果传回模型，模型整合结果生成最终回复。</li></ol><p><strong>Spring AI 的三种工具定义方式</strong>：</p><table><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">特点</th><th style="text-align:left;">适用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>注解式 <code>@Tool</code></strong></td><td style="text-align:left;">最常用，方法加注解即可</td><td style="text-align:left;">常规业务工具</td></tr><tr><td style="text-align:left;"><strong>函数式 <code>Function/BiFunction</code></strong></td><td style="text-align:left;">基于 JDK 函数式接口，代码极简</td><td style="text-align:left;">轻量工具</td></tr><tr><td style="text-align:left;"><strong>编程式 <code>ToolCallback</code></strong></td><td style="text-align:left;">手动构建工具元信息，最灵活</td><td style="text-align:left;">动态工具、插件化</td></tr></tbody></table><blockquote><p><strong>总结</strong>：Tool Calling 的本质是&quot;LLM 决策 + 应用执行&quot;的分工——LLM 负责理解意图和生成调用参数，应用层负责实际执行和结果回传，框架层（Spring AI、LangChain）负责中间的桥接和编排。</p></blockquote><h3 id="【困难】agent-的任务规划有哪些常见策略-plan-and-solve-和-react-各自适合什么场景-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】agent-的任务规划有哪些常见策略-plan-and-solve-和-react-各自适合什么场景-⭐⭐⭐"><span>【困难】Agent 的任务规划有哪些常见策略？Plan-and-Solve 和 ReAct 各自适合什么场景？⭐⭐⭐</span></a></h3><p>任务规划是 Agent 将复杂目标拆解为可执行子任务序列的核心能力，常见策略：</p><table><thead><tr><th style="text-align:left;">策略</th><th style="text-align:left;">原理</th><th style="text-align:left;">优势</th><th style="text-align:left;">劣势</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Plan-and-Solve</strong></td><td style="text-align:left;">先完整制定计划，再逐步执行</td><td style="text-align:left;">全局视野，结构清晰</td><td style="text-align:left;">计划可能因信息不足而错误</td></tr><tr><td style="text-align:left;"><strong>ReAct</strong></td><td style="text-align:left;">思考→行动→观察交替进行，边做边调整</td><td style="text-align:left;">灵活适应，实时纠错</td><td style="text-align:left;">缺乏全局规划</td></tr><tr><td style="text-align:left;"><strong>Reflexion</strong></td><td style="text-align:left;">在 ReAct 基础上增加评估和反思，跨任务学习</td><td style="text-align:left;">持续优化</td><td style="text-align:left;">需要多次试错</td></tr><tr><td style="text-align:left;"><strong>Tree-of-Thought</strong></td><td style="text-align:left;">将推理展开为树结构，搜索最优路径</td><td style="text-align:left;">探索空间大</td><td style="text-align:left;">计算开销高</td></tr><tr><td style="text-align:left;"><strong>LATS</strong></td><td style="text-align:left;">结合蒙特卡洛树搜索和 LLM 反思</td><td style="text-align:left;">平衡探索与利用</td><td style="text-align:left;">实现复杂</td></tr></tbody></table><p>注：CoT 属于纯提示词推理技巧，不涉及工具执行与状态管理，此处不展开；本题聚焦执行框架层面。</p><p><strong>从执行框架视角对比（循环结构/工具时机/状态管理/失败重试）</strong>：</p><table><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">ReAct</th><th style="text-align:left;">Plan-and-Solve</th><th style="text-align:left;">纯工作流</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>循环结构</strong></td><td style="text-align:left;">单层循环：Thought→Action→Observation 直到产出 Final Answer</td><td style="text-align:left;">双层：Planner 产出计划，Executor 逐项执行，可触发 Replan</td><td style="text-align:left;">无循环，固定 DAG</td></tr><tr><td style="text-align:left;"><strong>工具调用时机</strong></td><td style="text-align:left;">每轮由模型即时决定，无全局预算</td><td style="text-align:left;">计划阶段预见所需工具，可按子任务并行调用</td><td style="text-align:left;">节点位置写死</td></tr><tr><td style="text-align:left;"><strong>状态管理</strong></td><td style="text-align:left;">全部历史堆在上下文里，长任务易窗口溢出</td><td style="text-align:left;">计划+子任务状态显式存储，可持久化/断点恢复</td><td style="text-align:left;">状态结构化，最可控</td></tr><tr><td style="text-align:left;"><strong>失败重试</strong></td><td style="text-align:left;">靠模型看到错误 Observation 后自行调整，不可靠</td><td style="text-align:left;">子任务粒度重试，失败可跳过/重排/上报</td><td style="text-align:left;">节点级重试策略可配置</td></tr></tbody></table><p><strong>Plan-and-Solve vs ReAct 的选择</strong>：</p><ul><li><strong>Plan-and-Solve 适合</strong>：任务结构清晰、步骤明确的场景（如&quot;写一份报告：先调研→再分析→最后总结&quot;）。</li><li><strong>ReAct 适合</strong>：需要根据中间结果动态调整策略的场景（如&quot;帮我查某公司的最新财务状况&quot;——每一步搜索的结果决定下一步方向）。</li><li><strong>实际工程中</strong>：通常<strong>混合使用</strong>——先用 Plan-and-Solve 制定高层计划，执行每个子任务时用 ReAct 进行即时推理和调整。</li></ul><p><strong>真实踩坑案例（纯 ReAct 循环失控）</strong>：</p><ul><li><strong>现象</strong>：调研 Agent 用纯 ReAct 跑&quot;竞品分析&quot;任务，单次跑了 38 轮、消耗 14 美元 Token，最终产出大量重复内容。</li><li><strong>排查</strong>：Trace 显示 Agent 反复&quot;搜索→发现新线索→再搜索&quot;，在两个信息源之间打转，没有任何全局进度判断。</li><li><strong>根因</strong>：ReAct 只有局部视野——每一步只看当前 Observation，无人回答&quot;信息是否已经够&quot;，缺乏全局状态和预算约束。</li><li><strong>修复</strong>：改为 Plan-and-Solve 骨架（先列大纲，每个子任务标记完成状态）+ 子任务内部用 ReAct + 最大迭代预算 10 轮。同类任务平均 7 轮完成，成本下降 76%。</li></ul><blockquote><p><strong>总结</strong>：没有&quot;万能&quot;的规划策略——结构化任务用 Plan-and-Solve 先规划后执行，探索性任务用 ReAct 边想边做，高可靠性场景叠加 Reflexion 反思机制，实践中往往混合使用。关键工程约束：无论哪种策略，都必须配最大迭代次数、重复检测和预算兜底，自主性必须关在笼子里。</p></blockquote><h4 id="拓展追问-8" tabindex="-1"><a class="header-anchor" href="#拓展追问-8"><span>拓展追问</span></a></h4><ol><li>ReAct 为什么必须把 Observation 写回上下文？长任务下这种状态管理会遇到什么问题？<br> Observation 是模型感知外部世界的唯一通道，不写回就无法基于事实决策。但全部历史堆在上下文里，长任务会遇到：窗口溢出需要截断/摘要（可能丢关键信息）、Lost in the Middle 导致早期观察被忽略、成本随轮数线性增长。工程上需要定期压缩历史、显式维护任务状态对象，而不是只靠原始对话流。</li><li>Plan-and-Solve 的初始计划错了怎么办？Replan 的触发条件怎么设计？<br> 需要显式的 Replan 机制：子任务执行失败超过重试上限、Observation 与计划假设冲突（如预期能查到的数据不存在）、已完成结果推翻了后续步骤的前提，三者任一命中就携带已有结果回到 Planner 重新规划。关键是计划要以结构化状态存储（子任务列表 + 完成状态），而不是只存在于一段自然语言里，否则无法判断&quot;哪里变了&quot;。</li><li>确定性业务流程（如审批流、下单流）为什么根本不该用自主规划？<br> 因为这类流程的正确性要求是 100%，而自主规划每一步都有非零出错概率，步数一多整体可靠性必然下降；且合规审计需要可解释、可复现的执行路径。正确姿势是用固定工作流，只在意图理解、异常判断等少数节点嵌入 LLM，把非确定性控制在最小范围。</li></ol><h4 id="场景题-8" tabindex="-1"><a class="header-anchor" href="#场景题-8"><span>场景题</span></a></h4><p>你要构建一个&quot;读需求文档→写代码→跑测试→改 Bug&quot;的编码 Agent。请设计规划策略、状态管理和终止条件。</p><p><strong>参考答案</strong>：</p><ul><li><strong>规划策略</strong>：混合式——Plan-and-Solve 骨架：先解析需求产出任务计划（理解需求→定位代码→实现→测试→修复→总结），每个子任务内部用 ReAct 循环（写代码→跑测试→看报错→再改）。编码任务天然需要&quot;试错-观察-修正&quot;的局部循环，但全局顺序必须受控。</li><li><strong>状态管理</strong>：计划以结构化状态存储（子任务列表 + 状态 + 产物路径），每轮只把当前子任务相关的上下文（当前文件、最近一次测试输出）注入窗口，而非全量历史；测试报错只保留关键堆栈，避免信息洪水。</li><li><strong>终止条件</strong>：① 全部测试通过 + 计划全部标记完成→正常结束；② 最大迭代预算（如修复循环 ≤ 5 轮、总轮次 ≤ 15 轮）；③ 重复检测（连续两轮代码 diff 几乎相同且测试仍失败→判定僵局，上报人工）；④ 超时/Token 预算兜底，优雅退出时输出已完成部分和问题清单。</li><li><strong>权衡</strong>：全自动自主探索上限高但成本和不可控性也高；生产方案应把&quot;修不好就上报&quot;作为一等公民设计——Agent 承认失败并给出诊断，比硬跑 30 轮后交一份错误代码价值高得多。</li></ul><h3 id="【中等】什么是-reflexion-它和-react-有什么区别-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】什么是-reflexion-它和-react-有什么区别-⭐⭐⭐"><span>【中等】什么是 Reflexion？它和 ReAct 有什么区别？⭐⭐⭐</span></a></h3><p><strong>Reflexion</strong>（Shinn et al., 2023）是在 ReAct 基础上增加了**评估（Evaluator）<strong>和</strong>自我反思（Self-Reflection）**机制的框架，形成&quot;行动→评估→反思→迭代&quot;的学习闭环。</p><p><strong>与 ReAct 的核心区别</strong>：</p><table><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">ReAct</th><th style="text-align:left;">Reflexion</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>关注范围</strong></td><td style="text-align:left;">单次任务的即时推理-行动循环</td><td style="text-align:left;">跨任务的持续优化</td></tr><tr><td style="text-align:left;"><strong>经验保留</strong></td><td style="text-align:left;">不保留跨任务经验</td><td style="text-align:left;">将失败经验以语言形式存入记忆</td></tr><tr><td style="text-align:left;"><strong>纠错能力</strong></td><td style="text-align:left;">仅依赖当前轮次的观察进行调整</td><td style="text-align:left;">Evaluator 判断失败原因，生成反思指导下次</td></tr></tbody></table><p><strong>自我纠错机制</strong>：当 Agent 失败时 → Evaluator 判断失败原因 → Self-Reflection 生成文本反思（如&quot;上次用冷水无效，因为油渍需要热分解&quot;）→ 存入滑动窗口记忆（最多保留 3 条）→ 下次执行时作为上下文指导行动。</p><blockquote><p><strong>总结</strong>：ReAct 解决&quot;当下怎么想怎么做&quot;，Reflexion 解决&quot;这次失败了下次怎么改进&quot;——Reflexion = ReAct + 评估 + 反思记忆，实现了从即时推理到跨任务学习的进化。</p></blockquote><h3 id="【简单】autogpt-如何实现自主决策-⭐⭐" tabindex="-1"><a class="header-anchor" href="#【简单】autogpt-如何实现自主决策-⭐⭐"><span>【简单】AutoGPT 如何实现自主决策？⭐⭐</span></a></h3><p>AutoGPT 通过以下机制实现自主决策：</p><ol><li><strong>目标分解</strong>：以 LLM 为决策核心，接收高层目标后自主分解为子任务序列。</li><li><strong>自主循环</strong>：循环执行&quot;思考→规划→调用工具→观察结果→调整计划&quot;，无需人类逐步指令。</li><li><strong>工具集成</strong>：集成网络搜索、文件读写、代码执行等工具。</li><li><strong>记忆维持</strong>：通过短期记忆（上下文窗口）和长期记忆（向量数据库）维持任务状态。</li></ol><blockquote><p><strong>总结</strong>：AutoGPT 是 Agent 自主决策的典型代表，其核心模式是&quot;目标驱动 + 工具赋能 + 记忆持续 + 循环迭代&quot;。</p></blockquote><h3 id="【简单】llm-agent-在多模态任务中如何执行推理-⭐⭐" tabindex="-1"><a class="header-anchor" href="#【简单】llm-agent-在多模态任务中如何执行推理-⭐⭐"><span>【简单】LLM Agent 在多模态任务中如何执行推理？⭐⭐</span></a></h3><p>LLM Agent 通过多模态感知系统接收文本、图像、音频等不同模态的输入，由 LLM 统一理解后，按照 ReAct 等推理范式进行任务分解和工具调用。</p><p><strong>典型流程</strong>：接收图像 → OCR/视觉模型识别内容 → 调用搜索工具验证 → 整合信息生成结论。</p><p><strong>关键挑战</strong>：将多模态信息统一编码为 LLM 可理解的表示，并在推理链中协调不同模态的处理步骤。</p><blockquote><p><strong>总结</strong>：多模态推理的核心在于&quot;统一理解 + 分步处理&quot;——LLM 作为统一的理解层，根据输入模态动态选择处理工具和推理路径。</p></blockquote><h2 id="上下文管理与约束" tabindex="-1"><a class="header-anchor" href="#上下文管理与约束"><span>上下文管理与约束</span></a></h2><h3 id="【中等】什么是-agent-的上下文窗口-为什么它是-agent-工程中最核心的约束-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】什么是-agent-的上下文窗口-为什么它是-agent-工程中最核心的约束-⭐⭐⭐"><span>【中等】什么是 Agent 的上下文窗口？为什么它是 Agent 工程中最核心的约束？⭐⭐⭐</span></a></h3><p>上下文窗口是模型在一次交互中能处理的<strong>最大 Token 数量</strong>（包含输入 Prompt + 输出 Completion）。</p><p><strong>它是最核心约束的原因</strong>：</p><ol><li><strong>容量有限</strong>：Agent 需在窗口内同时容纳系统指令、工具定义、对话历史、工具返回结果和推理过程。</li><li><strong>成本递增</strong>：窗口越长，推理延迟和计算成本越高（注意力计算为 O(n²)）。</li><li><strong>信息丢失</strong>：超出窗口的内容会被截断，导致关键信息丢失。</li><li><strong>注意力衰减</strong>：即使在窗口范围内，模型对中间信息的注意力也可能下降（<strong>&quot;Lost in the Middle&quot;</strong> 现象）。</li></ol><blockquote><p><strong>总结</strong>：上下文窗口是 Agent 工程的&quot;物理天花板&quot;——所有架构设计（记忆分层、上下文压缩、工具结果处理）本质上都在与这个约束博弈。</p></blockquote><h3 id="【中等】当对话历史超出上下文窗口时-有哪些上下文压缩策略-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】当对话历史超出上下文窗口时-有哪些上下文压缩策略-⭐⭐⭐"><span>【中等】当对话历史超出上下文窗口时，有哪些上下文压缩策略？⭐⭐⭐</span></a></h3><table><thead><tr><th style="text-align:left;">策略</th><th style="text-align:left;">原理</th><th style="text-align:left;">优点</th><th style="text-align:left;">缺点</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>截断（Truncation）</strong></td><td style="text-align:left;">直接丢弃早期对话</td><td style="text-align:left;">简单高效</td><td style="text-align:left;">可能丢失关键信息</td></tr><tr><td style="text-align:left;"><strong>摘要压缩</strong></td><td style="text-align:left;">调用 LLM 将长对话压缩为摘要</td><td style="text-align:left;">保留核心语义</td><td style="text-align:left;">压缩消耗 Token，丢失细节</td></tr><tr><td style="text-align:left;"><strong>上下文卸载</strong></td><td style="text-align:left;">完整信息保存到外部文件，窗口中仅保留摘要和路径</td><td style="text-align:left;">信息不丢失，Token 节省最高 61%</td><td style="text-align:left;">需额外文件读取</td></tr><tr><td style="text-align:left;"><strong>分层保护</strong></td><td style="text-align:left;">标记关键内容为不可裁剪，仅压缩探索过程噪音</td><td style="text-align:left;">关键信息有保障</td><td style="text-align:left;">标记策略设计复杂</td></tr><tr><td style="text-align:left;"><strong>滑动窗口 + 重要性评分</strong></td><td style="text-align:left;">根据信息的重要性和时效性动态选择保留内容</td><td style="text-align:left;">动态适应</td><td style="text-align:left;">评分模型需调优</td></tr></tbody></table><blockquote><p><strong>总结</strong>：上下文压缩的核心原则是&quot;保重要、压次要、卸完整&quot;——关键信息留在窗口内，次要信息压缩为摘要，完整数据卸载到外部存储按需读取。</p></blockquote><h3 id="【中等】ai-agent-如何处理工具调用返回超大结果的问题-⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】ai-agent-如何处理工具调用返回超大结果的问题-⭐⭐"><span>【中等】AI Agent 如何处理工具调用返回超大结果的问题？⭐⭐</span></a></h3><table><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">原理</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>结果截断/分页</strong></td><td style="text-align:left;">对超大返回结果截断或分页，只注入最相关的部分</td></tr><tr><td style="text-align:left;"><strong>摘要化</strong></td><td style="text-align:left;">用 LLM 对工具返回的大结果进行摘要，注入摘要而非原始数据</td></tr><tr><td style="text-align:left;"><strong>上下文卸载</strong></td><td style="text-align:left;">完整结果保存到外部文件，窗口中仅保留摘要和文件路径</td></tr><tr><td style="text-align:left;"><strong>结构化提取</strong></td><td style="text-align:left;">从大结果中只提取与当前任务相关的关键字段</td></tr><tr><td style="text-align:left;"><strong>分层处理</strong></td><td style="text-align:left;">先用轻量模型/规则筛选，再用 LLM 处理筛选后的结果</td></tr></tbody></table><blockquote><p><strong>总结</strong>：处理超大结果的核心思路是&quot;先筛后注&quot;——通过截断、摘要、提取等手段将海量数据压缩到上下文可承载的密度，避免&quot;信息洪水&quot;淹没 Agent 的推理能力。</p></blockquote><h3 id="【中等】什么是-agent-的-guardrails-护栏-如何设计安全边界-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】什么是-agent-的-guardrails-护栏-如何设计安全边界-⭐⭐⭐"><span>【中等】什么是 Agent 的 Guardrails（护栏）？如何设计安全边界？⭐⭐⭐</span></a></h3><p><strong>Guardrails（护栏）</strong> 是在 Agent 系统中设置的<strong>安全约束和防护机制</strong>，用于确保 Agent 的行为在预期范围内，防止产生有害输出或执行危险操作。</p><p><strong>Guardrails 的设计层次</strong>：</p><table><thead><tr><th style="text-align:left;">层次</th><th style="text-align:left;">机制</th><th style="text-align:left;">示例</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>输入护栏</strong></td><td style="text-align:left;">过滤和验证用户输入</td><td style="text-align:left;">拒绝注入攻击、敏感话题过滤</td></tr><tr><td style="text-align:left;"><strong>输出护栏</strong></td><td style="text-align:left;">检查 Agent 生成的内容</td><td style="text-align:left;">有害内容检测、事实一致性校验</td></tr><tr><td style="text-align:left;"><strong>工具护栏</strong></td><td style="text-align:left;">限制工具调用的权限和范围</td><td style="text-align:left;">禁止删除操作、限制文件访问路径</td></tr><tr><td style="text-align:left;"><strong>流程护栏</strong></td><td style="text-align:left;">约束 Agent 的执行流程</td><td style="text-align:left;">最大迭代次数、超时机制、Token 预算</td></tr><tr><td style="text-align:left;"><strong>人工审核（HITL）</strong></td><td style="text-align:left;">关键操作需人工确认</td><td style="text-align:left;">高风险操作前的确认审批</td></tr></tbody></table><p><strong>主流框架</strong>：</p><ul><li><strong>NeMo Guardrails（NVIDIA）</strong>：通过 Colang 语言定义对话流和安全规则，支持输入/输出检查、话题限制。</li><li><strong>Guardrails AI</strong>：提供 <code>Guard</code> 和 <code>Validator</code> 机制，对 LLM 输出进行结构化验证和修正。</li></ul><blockquote><p><strong>总结</strong>：Guardrails 是 Agent 系统的&quot;安全网&quot;——输入端防注入、输出端防有害、工具端防越权、流程端防失控，多层防护确保 Agent 在生产环境中安全可控。</p></blockquote><h2 id="协议、标准与生态-mcp-a2a" tabindex="-1"><a class="header-anchor" href="#协议、标准与生态-mcp-a2a"><span>协议、标准与生态 (MCP &amp; A2A)</span></a></h2><h3 id="【中等】mcp-协议是什么-它在-ai-agent-系统中解决了什么问题-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】mcp-协议是什么-它在-ai-agent-系统中解决了什么问题-⭐⭐⭐⭐"><span>【中等】MCP 协议是什么？它在 AI Agent 系统中解决了什么问题？⭐⭐⭐⭐</span></a></h3><p><strong>MCP（Model Context Protocol，模型上下文协议）</strong> 是由 Anthropic 发布的开放标准，旨在为 LLM 应用与外部工具/数据源之间提供<strong>统一的连接接口</strong>。本题聚焦 Agent-to-Tool 连接层。</p><p><strong>解决的核心问题：M×N 集成困境</strong>。传统集成依赖硬编码 API 连接：M 个应用要接 N 个工具就需要 M×N 套适配器，每接入一个新工具都要定制开发。MCP 让每个应用和每个工具只实现一次标准协议，集成复杂度从 M×N 降为 <strong>M+N</strong>，实现&quot;即插即用&quot;。</p><p><strong>三原语：MCP Server 向应用暴露的三类能力</strong></p><table><thead><tr><th style="text-align:left;">原语</th><th style="text-align:left;">控制方</th><th style="text-align:left;">语义</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Tools</strong></td><td style="text-align:left;">模型控制</td><td style="text-align:left;">可调用的操作（有副作用），如&quot;发送邮件&quot;&quot;查数据库&quot;</td></tr><tr><td style="text-align:left;"><strong>Resources</strong></td><td style="text-align:left;">应用控制</td><td style="text-align:left;">只读上下文数据，如文件内容、数据库记录、日志</td></tr><tr><td style="text-align:left;"><strong>Prompts</strong></td><td style="text-align:left;">用户控制</td><td style="text-align:left;">Server 提供的可复用提示模板/工作流模板</td></tr></tbody></table><p><strong>传输层</strong>：基于 JSON-RPC 2.0，支持 <strong>stdio</strong>（本地进程，零网络开销）和 <strong>Streamable HTTP</strong>（远程，支持流式响应）两种传输模式，本地工具和云服务可用同一套语义接入。</p><p><strong>方案权衡：MCP vs 直接 Function Calling / 自包装 REST</strong></p><table><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">适用边界</th><th style="text-align:left;">失效场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>直接 Function Calling</strong></td><td style="text-align:left;">单模型、少量内部工具的简单场景</td><td style="text-align:left;">多模型/多应用共享工具时需重复适配，格式不统一</td></tr><tr><td style="text-align:left;"><strong>MCP</strong></td><td style="text-align:left;">多应用多工具、需跨模型复用、第三方工具生态</td><td style="text-align:left;">多一层 Server 部署运维；Server 质量参差时工具描述差导致误调用</td></tr></tbody></table><p><strong>真实踩坑案例（工具列表膨胀）</strong>：</p><ul><li><strong>现象</strong>：接入 12 个内部系统后，Agent 选错工具的比例明显上升，简单问题也要思考很久。</li><li><strong>排查</strong>：统计发现全量 200+ 工具的 Schema 描述占了约 18k Token 上下文，模型在海量工具里&quot;选择困难&quot;，且工具描述互相干扰。</li><li><strong>根因</strong>：MCP 解决了&quot;怎么接&quot;，但没解决&quot;接多少&quot;——把接入等同于全量暴露，上下文膨胀反过来压垮了工具选择准确率。</li><li><strong>修复</strong>：加意图路由层，先对用户请求分类，再动态只注入相关 Server 的工具（单次 ≤ 15 个）；工具选择准确率从 78% 回升到 93%，新工具接入工时从平均 3 人天降到 0.5 人天。</li></ul><blockquote><p><strong>总结</strong>：MCP 之于 AI Agent，犹如 USB 之于外设——一个标准化接口，把 M×N 的集成地狱降为 M+N，用 Tools/Resources/Prompts 三原语统一能力暴露方式。但它不是银弹：工具列表治理、Server 质量与安全审计，是接入后真正的运维难点。</p></blockquote><h4 id="拓展追问-9" tabindex="-1"><a class="header-anchor" href="#拓展追问-9"><span>拓展追问</span></a></h4><ol><li>Tools、Resources、Prompts 三原语的定位差异是什么？为什么区分&quot;只读 Resources&quot;和&quot;可执行 Tools&quot;很重要？<br> 差异在控制权与副作用：Resources 是应用按需读取的只读数据（无副作用、可预加载），Tools 是模型决策调用的操作（有副作用、需授权审计），Prompts 是面向用户的模板。区分只读与可执行直接决定安全策略：读可以宽松预取，写必须最小权限 + 审计，这是权限模型设计的基础。</li><li>MCP 解决 M×N 问题的边界在哪？哪些问题它解决不了？<br> MCP 解决的是&quot;接口标准化&quot;，解决不了：① 工具语义质量——描述写得差，模型照样误调用；② 工具数量治理——全量注入会压垮上下文；③ 业务级权限——协议层鉴权不能替代数据级权限控制。这些都需要应用层自建能力配套。</li><li>接入的 MCP Server 很多、工具列表很长时，工程上怎么处理上下文膨胀？<br> 三级策略：① 意图路由：先分类再动态选择相关 Server，只注入子集（单次 ≤ 15 个工具）；② 工具描述瘦身：只保留名称 + 一句话用途，详细参数说明改为模型选中后再加载；③ 分层暴露：高频工具常驻，低频工具通过&quot;工具目录查询工具&quot;按需发现。</li></ol><h4 id="场景题-9" tabindex="-1"><a class="header-anchor" href="#场景题-9"><span>场景题</span></a></h4><p>公司有 20 个遗留内部系统（部分连 OpenAPI 文档都没有），现在要统一接入 Agent 平台。请给出 MCP 落地路线图和风险预案。</p><p><strong>参考答案</strong>：</p><ul><li><strong>分批接入策略</strong>：按&quot;价值×改造成本&quot;排序——第一批选 3~5 个有现成 API 的高价值系统（如工单、知识库、审批），用官方 SDK 包一层 MCP Server 验证端到端；无 API 的遗留系统放在第二批，先评估补建 API 还是用数据库直连/RPA 过渡。</li><li><strong>规范先行</strong>：制定内部 MCP Server 开发规范——工具命名/描述写作指南（描述质量直接决定调用准确率）、参数 Schema 要求、错误码约定、权限声明；配套接入验收测试（每个工具至少 10 条调用用例）。</li><li><strong>风险预案</strong>：① 上下文膨胀：从第一天就上意图路由 + 工具子集注入，不要等 200 个工具接完再治理；② 安全：写操作类 Server 必须支持审计日志和权限校验，敏感数据类 Resources 走脱敏层；③ Server 质量参差：建立工具调用成功率监控，成功率低的工具下线整改而非勉强用。</li><li><strong>权衡</strong>：全量一次性接入周期长且风险集中，分批能持续交付价值但需要维护新老两套过渡；量化目标建议：单个系统接入 ≤ 1 人天、工具选择准确率 ≥ 90% 才允许接入下一批。</li></ul><h3 id="【中等】mcp-协议的架构包含哪些核心组件-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】mcp-协议的架构包含哪些核心组件-⭐⭐⭐"><span>【中等】MCP 协议的架构包含哪些核心组件？⭐⭐⭐</span></a></h3><p>MCP 采用客户端-服务器架构，三大核心组件：</p><table><thead><tr><th style="text-align:left;">组件</th><th style="text-align:left;">职责</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>MCP Host</strong></td><td style="text-align:left;">运行 LLM 的应用（如 Claude Desktop、IDE），管理 Client 生命周期</td></tr><tr><td style="text-align:left;"><strong>MCP Client</strong></td><td style="text-align:left;">Host 内的通信代理，与 Server 保持一对一连接，封装/转发标准化请求</td></tr><tr><td style="text-align:left;"><strong>MCP Server</strong></td><td style="text-align:left;">连接具体工具/数据源的功能适配器，接收请求、执行操作、返回结果</td></tr></tbody></table><p>通信基于 <strong>JSON-RPC 2.0</strong>，支持 <strong>stdio</strong>（本地）和 <strong>HTTP/SSE</strong>（远程）两种传输模式。</p><blockquote><p><strong>总结</strong>：MCP 的 Host-Client-Server 三层架构实现了 LLM 与工具的解耦——Host 管 LLM 集成，Client 管通信协议，Server 管工具适配。</p></blockquote><h3 id="【简单】mcp-的工作流程是什么-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【简单】mcp-的工作流程是什么-⭐⭐⭐"><span>【简单】MCP 的工作流程是什么？⭐⭐⭐</span></a></h3><p>MCP 的典型工作流分三个阶段：</p><ol><li><strong>初始化</strong>：Client 和 Server 交换并协商能力，就协议版本达成一致。</li><li><strong>操作</strong>：用户发起请求 → Host 将上下文和工具清单提供给 LLM → LLM 生成结构化 JSON 调用意图 → Client 通过 JSON-RPC 发送至 Server → Server 执行操作 → 结果回传 → LLM 评估后生成最终响应或继续下一轮调用。</li><li><strong>关闭</strong>：连接优雅关闭。</li></ol><blockquote><p><strong>总结</strong>：MCP 工作流 = 初始化握手 → 请求-调用-返回循环 → 优雅关闭，核心是 LLM 决策 + JSON-RPC 通信 + Server 执行的三方协作。</p></blockquote><h3 id="【中等】mcp-协议安全性设计包含哪些层面-⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】mcp-协议安全性设计包含哪些层面-⭐⭐"><span>【中等】MCP 协议安全性设计包含哪些层面？⭐⭐</span></a></h3><p>MCP 的安全性设计涵盖五个层面：</p><ol><li><strong>访问隔离</strong>：LLM 不直接访问系统资源，所有操作经 MCP Server 中转，控制数据边界。</li><li><strong>授权认证</strong>：支持 <strong>OAuth 2.1</strong> 进行授权认证。</li><li><strong>Root 机制</strong>：限制 Server 可访问的文件和目录范围。</li><li><strong>Sampling 审查</strong>：Sampling 功能要求用户审查和批准后才能传递给 LLM。</li><li><strong>传输加密</strong>：支持 HTTPS/TLS 加密传输。</li></ol><blockquote><p><strong>总结</strong>：MCP 安全设计的核心思想是&quot;LLM 不碰底层&quot;——通过 Server 中转、权限限制、人工审查三层隔离，确保 Agent 的工具调用安全可控。</p></blockquote><h3 id="【简单】如何将已有的应用转换成-mcp-服务-⭐⭐" tabindex="-1"><a class="header-anchor" href="#【简单】如何将已有的应用转换成-mcp-服务-⭐⭐"><span>【简单】如何将已有的应用转换成 MCP 服务？⭐⭐</span></a></h3><p>将已有应用转换为 MCP Server 的步骤：</p><ol><li><strong>实现接口规范</strong>：定义工具的名称、描述和参数 Schema。</li><li><strong>选择传输方式</strong>：本地 stdio 或远程 HTTP/SSE。</li><li><strong>封装已有功能</strong>：使用官方 SDK（Python、TypeScript、Java 等）封装。</li><li><strong>注册 Server</strong>：在 MCP Host 中注册 Server 地址。</li></ol><p>Anthropic 提供了官方 SDK，社区也有 <code>fastmcp</code> 等便捷实现。</p><blockquote><p><strong>总结</strong>：已有应用接入 MCP 的关键是&quot;包一层标准协议&quot;——内部逻辑不变，对外暴露符合 MCP 规范的工具接口。</p></blockquote><h3 id="【中等】什么是-a2a-协议-它和-mcp-协议有什么区别-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】什么是-a2a-协议-它和-mcp-协议有什么区别-⭐⭐⭐⭐"><span>【中等】什么是 A2A 协议？它和 MCP 协议有什么区别？⭐⭐⭐⭐</span></a></h3><p><strong>A2A（Agent-to-Agent）协议</strong>是由 Google 发起、50+ 合作伙伴共同贡献的开源通信标准，旨在让不同厂商、不同框架构建的 AI Agent 能够协同工作。本题聚焦 Agent-to-Agent 协作层（工具连接层的细节见 MCP 相关题目，此处不重复）。</p><p><strong>与 MCP 的定位差异</strong>：</p><table><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">MCP</th><th style="text-align:left;">A2A</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>连接方向</strong></td><td style="text-align:left;">纵向：Agent ↔ 工具/数据源</td><td style="text-align:left;">横向：Agent ↔ Agent</td></tr><tr><td style="text-align:left;"><strong>解决问题</strong></td><td style="text-align:left;">Agent 如何使用外部工具</td><td style="text-align:left;">Agent 之间如何协作</td></tr><tr><td style="text-align:left;"><strong>比喻</strong></td><td style="text-align:left;">Agent 的&quot;手&quot;（连接工具）</td><td style="text-align:left;">Agent 之间的&quot;语言&quot;（协作通信）</td></tr><tr><td style="text-align:left;"><strong>关系</strong></td><td style="text-align:left;">两者互补，一个完整的 Agent 系统通常同时使用两者</td><td style="text-align:left;"></td></tr></tbody></table><p><strong>A2A 协作的两个核心机制</strong>：</p><ul><li><strong>Agent Card（服务发现）</strong>：每个 Agent 发布在 <code>/.well-known/agent.json</code> 的机器可读名片，声明身份、能力（Skills）、端点和安全要求，让编排 Agent 能自动发现&quot;谁能干这个活&quot;。</li><li><strong>任务生命周期（状态管理）</strong>：Task 是协作的最小调度单元，状态机为：已提交→处理中→需输入→已完成/失败/已取消，长任务通过 SSE 实时推送状态，天然支持跨小时甚至跨天的异步协作。</li></ul><p><strong>方案权衡：A2A 协议协作 vs 单框架内多 Agent 编排</strong></p><table><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">适用边界</th><th style="text-align:left;">失效场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>单框架内编排（如 LangGraph）</strong></td><td style="text-align:left;">同一团队、同一技术栈、需要共享状态的多 Agent</td><td style="text-align:left;">跨团队/跨厂商协作时需共享内部实现，耦合严重</td></tr><tr><td style="text-align:left;"><strong>A2A 协议协作</strong></td><td style="text-align:left;">跨团队、跨框架、跨组织的 Agent 互操作</td><td style="text-align:left;">同团队内部使用则协议开销大于收益；Agent Card 自报能力可能失真</td></tr></tbody></table><p><strong>真实踩坑案例（Agent Card 能力虚报导致误派发）</strong>：</p><ul><li><strong>现象</strong>：跨团队协作中，编排 Agent 把&quot;合同风险审查&quot;任务派给了&quot;法务问答 Agent&quot;，产出牛头不对马嘴但状态显示&quot;已完成&quot;。</li><li><strong>排查</strong>：该 Agent 的 Agent Card 描述里含&quot;合同&quot;关键词，但实际只做法律常识问答，从未做过审查任务；调度只做了关键词匹配。</li><li><strong>根因</strong>：Agent Card 能力是自报的且无验证机制，调度端只看描述不看实证。</li><li><strong>修复</strong>：① Agent Card 规范化：结构化技能清单 + 附带能力测试用例；② 任务结果附置信度自评，低置信触发复核；③ 编排端抽样 5% 任务产出质检。误派率从 9% 降到 1%。</li></ul><blockquote><p><strong>总结</strong>：MCP 解决&quot;Agent 怎么用工具&quot;，A2A 解决&quot;Agent 怎么合作&quot;——MCP 是纵向连接，A2A 是横向协作，二者互补构成完整的 Agent 生态。A2A 的落地难点不在协议本身，而在能力声明的真实性验证和任务生命周期的异常处理。</p></blockquote><h4 id="拓展追问-10" tabindex="-1"><a class="header-anchor" href="#拓展追问-10"><span>拓展追问</span></a></h4><ol><li>A2A 为什么强调&quot;不透明代理&quot;（Agent 间不共享内部记忆/工具/推理）？这对跨厂商协作意味着什么？<br> 不透明意味着协作只依赖&quot;能力声明 + 任务交付&quot;两个接口，内部实现完全黑盒。这让不同厂商、不同框架、甚至互为竞争对手的 Agent 也能协作——不用交换内部状态就没有数据泄露和商业机密问题，代价是协作粒度只能到任务级，无法做细粒度的中间状态协同。</li><li>长时间任务为什么需要&quot;需输入&quot;状态和 SSE 推送？同步 HTTP 等待有什么问题？<br> 同步等待意味着连接长开、网关超时（通常 30~60 秒）、客户端崩溃即任务丢失。状态机 + SSE 把协作变成异步：任务提交后立即返回任务 ID，进度通过 SSE 推送，中途需要补充信息时转入&quot;需输入&quot;状态等客户端回注，任务状态服务端持久化，客户端随时可重连查询——这是数小时级任务能可靠运行的前提。</li><li>公司内部 Agent 都是自研的，还有必要引入 A2A 吗？<br> 看组织边界而非技术边界：若各 Agent 属同一团队、同一技术栈，直接用框架内编排更简单；若分属不同部门/事业部、各自迭代发布，A2A 的价值就出现了——它把&quot;跨团队协作接口&quot;标准化，避免两两定制对接。判断标准是&quot;对接数量是否随团队数平方增长&quot;。</li></ol><h4 id="场景题-10" tabindex="-1"><a class="header-anchor" href="#场景题-10"><span>场景题</span></a></h4><p>集团三个事业部各自建设了 Agent（报销 Agent、审批 Agent、财务 Agent，技术栈各异），现在要提供统一入口&quot;一句话报销&quot;，需要跨三个系统协作。请设计协作架构。</p><p><strong>参考答案</strong>：</p><ul><li><strong>架构设计</strong>：编排 Agent（Orchestrator）作为统一入口：① 三个事业部 Agent 各自发布 Agent Card，声明技能（&quot;发起报销&quot;&quot;查审批状态&quot;&quot;查付款进度&quot;）与鉴权方式；② 编排 Agent 解析用户请求后，按 Agent Card 能力匹配派发子任务；③ 子任务间有依赖（报销单创建→审批状态跟踪→付款查询），编排端维护任务 DAG，可串行/并行调度；④ 结果以 Artifact 结构化返回，编排 Agent 汇总后回复用户。</li><li><strong>关键机制</strong>：① 任务 ID 全链路透传，支持端到端追踪；② 长审批任务用 SSE 状态推送，用户可随时问&quot;我的报销到哪了&quot;；③ 任一子任务失败时编排 Agent 明确告知失败环节，而不是静默吞掉。</li><li><strong>风险与预案</strong>：① 能力虚报：Agent Card 上线需附验收用例；② 责任边界：跨部门数据（财务信息）需在各 Agent 侧做权限校验，编排 Agent 不代理鉴权；③ 版本演进：Agent Card 能力变更需兼容旧版或显式升版本，避免静默破坏编排逻辑。</li><li><strong>权衡</strong>：三系统同公司，也可以强行统一技术栈后框架内编排——但改造成本和跨部门协调成本远高于接入 A2A；协议层解耦的本质是&quot;用标准化接口换组织协作成本&quot;，组织边界越清晰越值得。</li></ul><h3 id="【中等】a2a-协议中的-agent-card-是什么-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】a2a-协议中的-agent-card-是什么-⭐⭐⭐"><span>【中等】A2A 协议中的 Agent Card 是什么？⭐⭐⭐</span></a></h3><p><strong>Agent Card</strong> 是每个 A2A Agent 的&quot;数字名片&quot;，是发布在已知路径（如 <code>/.well-known/agent.json</code>）的 JSON 文件。</p><p><strong>包含内容</strong>：Agent 的唯一身份标识、功能描述（Skills）、访问端点 URL、支持的交互模态、安全需求声明等。</p><p><strong>作用</strong>：让客户端 Agent 能够<strong>自动发现并评估</strong>哪个远程 Agent 适合处理特定任务，是多 Agent 协作中的&quot;服务发现&quot;机制。</p><blockquote><p><strong>总结</strong>：Agent Card 之于 A2A，如同 DNS 之于互联网——通过标准化的&quot;名片&quot;让 Agent 能被自动发现和识别。</p></blockquote><h3 id="【中等】a2a-协议的核心架构及主要组件有哪些-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】a2a-协议的核心架构及主要组件有哪些-⭐⭐⭐"><span>【中等】A2A 协议的核心架构及主要组件有哪些？⭐⭐⭐</span></a></h3><p>A2A 采用客户端-服务器架构，四大核心数据模型：</p><table><thead><tr><th style="text-align:left;">组件</th><th style="text-align:left;">定义</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Agent Card</strong></td><td style="text-align:left;">Agent 的机器可读名片，包含身份、能力、端点等信息</td></tr><tr><td style="text-align:left;"><strong>Task（任务）</strong></td><td style="text-align:left;">最小可调度单元，生命周期：已提交→处理中→需输入→已完成/失败/已取消</td></tr><tr><td style="text-align:left;"><strong>Message（消息）</strong></td><td style="text-align:left;">Task 内所有交互消息的统一载体（文本、文件、数据、表单等）</td></tr><tr><td style="text-align:left;"><strong>Artifact（工件）</strong></td><td style="text-align:left;">Task 完成后的结构化输出物，确保输出的一致性和易用性</td></tr></tbody></table><blockquote><p><strong>总结</strong>：A2A 的四大组件构成完整的任务生命周期——Agent Card 负责发现，Task 负责调度，Message 负责通信，Artifact 负责交付。</p></blockquote><h3 id="【简单】a2a-协议有哪五大设计原则-⭐⭐" tabindex="-1"><a class="header-anchor" href="#【简单】a2a-协议有哪五大设计原则-⭐⭐"><span>【简单】A2A 协议有哪五大设计原则？⭐⭐</span></a></h3><ol><li><strong>关注 Agent 能力（不透明代理）</strong>：Agent 之间无需共享内部记忆、逻辑或工具，只关注&quot;对话内容&quot;和&quot;任务交付&quot;。</li><li><strong>采用通用 Web 标准</strong>：基于 HTTP、SSE、JSON-RPC 2.0 等成熟标准，降低集成门槛。</li><li><strong>内置安全性</strong>：原生支持 API Key、OAuth2、OpenID Connect、mTLS 等认证方案。</li><li><strong>支持长时间任务</strong>：能处理耗时数小时甚至数天的任务，提供实时状态更新。</li><li><strong>处理多样化数据类型</strong>：原生支持文本、音频、视频和交互式表单等多模态数据。</li></ol><blockquote><p><strong>总结</strong>：A2A 的设计哲学是&quot;能力透明、内部黑盒&quot;——只暴露&quot;能做什么&quot;和&quot;怎么通信&quot;，不暴露&quot;怎么做&quot;。</p></blockquote><h3 id="【中等】a2a-协议的工作流程是怎样的-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】a2a-协议的工作流程是怎样的-⭐⭐⭐"><span>【中等】A2A 协议的工作流程是怎样的？⭐⭐⭐</span></a></h3><p>A2A 遵循客户端-服务器模型，一个 Agent（客户端）请求执行任务，另一个 Agent（服务器）执行任务，角色可在对话中互换。</p><p><strong>具体工作流</strong>：</p><ol><li><strong>服务发现</strong>：客户端 Agent 检查远程 Agent 的 Agent Card，确认能力匹配。</li><li><strong>任务发起</strong>：通过 <code>SendMessage</code> 或 <code>SendStreamingMessage</code> 发起任务请求。</li><li><strong>任务执行</strong>：远程 Agent 接收任务，状态变为&quot;处理中&quot;，执行过程中可通过 <code>GetTask</code> 查询进度。</li><li><strong>实时推送</strong>：对于长任务，通过 SSE 实时推送状态更新。</li><li><strong>结果返回</strong>：任务完成后，远程 Agent 以 Artifact 格式返回结构化结果。</li><li><strong>任务终止</strong>：如需终止，可调用 <code>CancelTask</code>。</li></ol><blockquote><p><strong>总结</strong>：A2A 工作流 = Agent Card 发现 → 任务创建 → 执行+状态推送 → Artifact 交付，本质上是标准化的&quot;请求-执行-交付&quot;异步协作模式。</p></blockquote><h3 id="【简单】a2a-协议与-mcp-协议如何协同工作-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【简单】a2a-协议与-mcp-协议如何协同工作-⭐⭐⭐"><span>【简单】A2A 协议与 MCP 协议如何协同工作？⭐⭐⭐</span></a></h3><p>两者是互补关系，解决不同层面的问题：</p><ul><li><strong>MCP</strong>：纵向连接——Agent ↔ 工具/数据源，解决&quot;Agent 如何使用工具&quot;。</li><li><strong>A2A</strong>：横向协作——Agent ↔ Agent，解决&quot;Agent 之间如何协作&quot;。</li></ul><p><strong>多 Agent 系统架构设计</strong>：</p><ul><li><strong>Agent 内部</strong>：每个 Agent 通过 MCP 连接各自的工具集（数据库、搜索引擎、文件系统等）。</li><li><strong>Agent 之间</strong>：通过 A2A 进行横向协作，每个 Agent 发布 Agent Card 声明能力。</li><li><strong>编排层</strong>：主 Agent（Orchestrator）通过 A2A 发现并调度专业 Agent。</li></ul><p><strong>示例</strong>：用户问&quot;分析竞品并生成报告&quot;→ 编排 Agent 通过 A2A 分发给&quot;搜索 Agent&quot;（MCP 连接搜索引擎）和&quot;数据分析 Agent&quot;（MCP 连接数据库）→ 各自完成后通过 A2A Artifact 返回结果 → 编排 Agent 汇总生成报告。</p><blockquote><p><strong>总结</strong>：MCP 让每个 Agent &quot;手中有工具&quot;，A2A 让多个 Agent &quot;协同有语言&quot;——一个完整的 Agent 生态需要同时具备纵向工具连接和横向协作通信。</p></blockquote><h2 id="系统架构、安全与工程化" tabindex="-1"><a class="header-anchor" href="#系统架构、安全与工程化"><span>系统架构、安全与工程化</span></a></h2><h3 id="【中等】什么是-agent-loop-智能体循环-agent-的工作过程是怎样的-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】什么是-agent-loop-智能体循环-agent-的工作过程是怎样的-⭐⭐⭐"><span>【中等】什么是 Agent Loop（智能体循环）？Agent 的工作过程是怎样的？⭐⭐⭐</span></a></h3><p><strong>Agent Loop</strong> 是 OpenAI Codex 核心架构，是将用户意图、模型大脑和执行工具串联成闭环的系统。Agent 的工作过程遵循&quot;<strong>感知→规划→执行→反思</strong>&quot;的四阶闭环：</p><ol><li><strong>构建 Prompt（感知）</strong>：将用户输入、系统指令、工具定义、历史上下文组装为完整 Prompt。</li><li><strong>模型推理（规划）</strong>：LLM 分析意图，决定下一步行动（直接回复或调用工具）。</li><li><strong>工具调用（执行）</strong>：若需调用工具，执行对应的 API/函数，获取结果。</li><li><strong>结果反馈（反思）</strong>：将工具返回结果注入上下文，检查是否达标。若未达标则调整计划，回到步骤 2 继续推理。</li><li><strong>循环终止</strong>：当 LLM 判断任务完成，生成最终响应。</li></ol><p>整个过程由 LLM 驱动，记忆模块持续存储相关信息，规划模块根据执行情况动态调整。</p><blockquote><p><strong>总结</strong>：Agent Loop 的本质是&quot;Prompt → 推理 → 行动 → 反馈&quot;的无限循环，直到 LLM 认为任务完成或被外部终止——所有 Agent 框架的核心都是这个循环的不同实现。</p></blockquote><h3 id="【中等】agent-系统中如何设计终止条件-如何解决死循环问题-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】agent-系统中如何设计终止条件-如何解决死循环问题-⭐⭐⭐"><span>【中等】Agent 系统中如何设计终止条件？如何解决死循环问题？⭐⭐⭐</span></a></h3><p><strong>常见终止条件</strong>：</p><table><thead><tr><th style="text-align:left;">策略</th><th style="text-align:left;">原理</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>任务完成判定</strong></td><td style="text-align:left;">LLM 明确输出&quot;任务完成&quot;标记或 Final Answer</td></tr><tr><td style="text-align:left;"><strong>最大迭代次数</strong></td><td style="text-align:left;">设置硬性上限（如 5-10 轮），防止无限循环</td></tr><tr><td style="text-align:left;"><strong>重复检测</strong></td><td style="text-align:left;">同一 Action 连续出现且 Observation 不变，判定为陷入僵局</td></tr><tr><td style="text-align:left;"><strong>平台期检测</strong></td><td style="text-align:left;">连续 N 轮未发现新问题且老问题未减少，判定为收敛</td></tr><tr><td style="text-align:left;"><strong>Token 预算</strong></td><td style="text-align:left;">设置 Token 消耗上限，超出后强制终止</td></tr><tr><td style="text-align:left;"><strong>超时机制</strong></td><td style="text-align:left;">设置时间上限</td></tr></tbody></table><p><strong>死循环的典型场景</strong>：Agent 在两个方案间反复横跳，或反复调用同一工具得到相同结果。</p><p><strong>解决策略</strong>：</p><ol><li><strong>硬性上限</strong>：设置最大迭代次数（如 10 轮）。</li><li><strong>重复检测</strong>：连续执行相同 Action 且 Observation 不变，强制终止。</li><li><strong>反思介入</strong>：让 Agent 意识到自己在重复，主动切换策略。</li><li><strong>预算兜底</strong>：Token/时间预算超出后强制退出并返回部分结果。</li></ol><blockquote><p><strong>总结</strong>：终止条件设计的关键是&quot;多重保险&quot;——完成判定为主、迭代次数为底、重复检测为辅、预算超时兜底，确保 Agent 在任何情况下都能优雅退出。</p></blockquote><h3 id="【中等】多-agent-协作有哪些常见的编排模式-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】多-agent-协作有哪些常见的编排模式-⭐⭐⭐"><span>【中等】多 Agent 协作有哪些常见的编排模式？⭐⭐⭐</span></a></h3><table><thead><tr><th style="text-align:left;">编排模式</th><th style="text-align:left;">原理</th><th style="text-align:left;">适用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>顺序编排（Sequential）</strong></td><td style="text-align:left;">Agent A 的输出作为 Agent B 的输入</td><td style="text-align:left;">流水线任务（研究→写作→审校）</td></tr><tr><td style="text-align:left;"><strong>并行编排（Parallel）</strong></td><td style="text-align:left;">多个 Agent 同时处理独立子任务</td><td style="text-align:left;">可并行的场景（同时搜索多数据源）</td></tr><tr><td style="text-align:left;"><strong>层级编排（Hierarchical）</strong></td><td style="text-align:left;">主 Agent 分配任务给子 Agent，完成后汇报</td><td style="text-align:left;">复杂多步骤任务</td></tr><tr><td style="text-align:left;"><strong>辩论/投票模式</strong></td><td style="text-align:left;">多个 Agent 对同一问题给出答案，投票达成共识</td><td style="text-align:left;">需要高准确性的决策场景</td></tr></tbody></table><blockquote><p><strong>总结</strong>：编排模式的选择取决于任务的依赖关系——串行依赖用顺序、独立子任务用并行、层级分解用层级、需要共识用投票。</p></blockquote><h3 id="【中等】子-agent-subagent-模式有什么优势和挑战-⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】子-agent-subagent-模式有什么优势和挑战-⭐⭐"><span>【中等】子 Agent（Subagent）模式有什么优势和挑战？⭐⭐</span></a></h3><p><strong>优势</strong>：</p><ul><li><strong>任务隔离</strong>：每个子 Agent 专注单一职责，降低复杂度。</li><li><strong>上下文精简</strong>：子 Agent 只接收与其任务相关的信息，避免上下文污染。</li><li><strong>可复用性</strong>：子 Agent 可被不同父 Agent 复用。</li></ul><p><strong>挑战与边界问题</strong>：</p><table><thead><tr><th style="text-align:left;">问题</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>通信开销</strong></td><td style="text-align:left;">父子 Agent 间的信息传递消耗额外 Token</td></tr><tr><td style="text-align:left;"><strong>状态同步</strong></td><td style="text-align:left;">子 Agent 的执行状态需要反馈给父 Agent</td></tr><tr><td style="text-align:left;"><strong>错误传播</strong></td><td style="text-align:left;">子 Agent 的错误可能影响父 Agent 的决策</td></tr><tr><td style="text-align:left;"><strong>权限边界</strong></td><td style="text-align:left;">子 Agent 的工具权限应 ≤ 父 Agent（最小权限原则）</td></tr></tbody></table><blockquote><p><strong>总结</strong>：子 Agent 模式的核心价值是&quot;分治&quot;——隔离复杂度、精简上下文、提升复用性，但要警惕通信开销、错误传播和权限越界。</p></blockquote><h3 id="【中等】agent-系统中的-function-calling-和-mcp-有什么区别-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】agent-系统中的-function-calling-和-mcp-有什么区别-⭐⭐⭐"><span>【中等】Agent 系统中的 Function Calling 和 MCP 有什么区别？⭐⭐⭐</span></a></h3><table><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">Function Calling</th><th style="text-align:left;">MCP</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>定义</strong></td><td style="text-align:left;">模型原生能力，由模型提供商定义</td><td style="text-align:left;">标准化协议层，独立于模型</td></tr><tr><td style="text-align:left;"><strong>工具定义</strong></td><td style="text-align:left;">直接嵌入 API 请求中</td><td style="text-align:left;">通过 MCP Server 独立部署</td></tr><tr><td style="text-align:left;"><strong>优点</strong></td><td style="text-align:left;">简单直接，无需额外基础设施</td><td style="text-align:left;">统一接口，工具可跨模型复用，支持动态发现</td></tr><tr><td style="text-align:left;"><strong>缺点</strong></td><td style="text-align:left;">工具与模型强耦合，不同模型格式不统一</td><td style="text-align:left;">需部署和维护 MCP Server，架构更复杂</td></tr></tbody></table><blockquote><p><strong>总结</strong>：Function Calling 是&quot;模型内置的工具接口&quot;，MCP 是&quot;独立的工具标准协议&quot;——前者简单但耦合，后者复杂但解耦，生产级系统通常用 MCP 统一管理工具。</p></blockquote><h3 id="【中等】如何设计-ai-agent-的工具权限控制-⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】如何设计-ai-agent-的工具权限控制-⭐⭐"><span>【中等】如何设计 AI Agent 的工具权限控制？⭐⭐</span></a></h3><p><strong>设计原则</strong>：</p><ul><li><strong>最小权限原则</strong>：每个 Agent 只授予完成其任务所需的最小工具集。</li><li><strong>分级授权</strong>：读操作（查询）权限宽松，写操作（修改/删除）权限严格，需人工审批。</li><li><strong>沙箱隔离</strong>：代码执行类工具在沙箱中运行，限制文件系统访问范围。</li><li><strong>审计日志</strong>：记录所有工具调用行为，支持事后追溯和异常检测。</li><li><strong>人工审核（HITL）</strong>：高风险操作（如资金转账、数据删除）需人工确认后方可执行。</li></ul><blockquote><p><strong>总结</strong>：工具权限控制的核心是&quot;最小权限 + 分级授权 + 关键操作人工审批&quot;，确保 Agent 有能力完成任务但不越权。</p></blockquote><h3 id="【困难】如何评估-agent-系统的效果-有哪些评估指标和框架-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何评估-agent-系统的效果-有哪些评估指标和框架-⭐⭐⭐⭐"><span>【困难】如何评估 Agent 系统的效果？有哪些评估指标和框架？⭐⭐⭐⭐</span></a></h3><p>Agent 系统评估是一个多维度问题，需要覆盖从单步推理到端到端任务完成的全链路。</p><p><strong>核心评估维度</strong>：</p><table><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">评估内容</th><th style="text-align:left;">常用指标</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>任务完成率</strong></td><td style="text-align:left;">Agent 是否成功完成用户指定的任务</td><td style="text-align:left;">成功率（Success Rate）</td></tr><tr><td style="text-align:left;"><strong>推理质量</strong></td><td style="text-align:left;">推理链的逻辑正确性和效率</td><td style="text-align:left;">步骤准确率、推理步数</td></tr><tr><td style="text-align:left;"><strong>工具使用准确性</strong></td><td style="text-align:left;">是否选择了正确的工具并传入正确参数</td><td style="text-align:left;">工具选择准确率、参数准确率</td></tr><tr><td style="text-align:left;"><strong>幻觉率</strong></td><td style="text-align:left;">输出中是否包含与事实不符的内容</td><td style="text-align:left;">幻觉率（Faithfulness Score）</td></tr><tr><td style="text-align:left;"><strong>延迟与成本</strong></td><td style="text-align:left;">端到端响应时间和 Token 消耗</td><td style="text-align:left;">P50/P95 延迟、Token 成本</td></tr><tr><td style="text-align:left;"><strong>安全与合规</strong></td><td style="text-align:left;">是否触发 Guardrails、是否有越权操作</td><td style="text-align:left;">违规率、护栏触发率</td></tr></tbody></table><p><strong>方案权衡：离线基准评测 vs 线上评估；自动裁判 vs 人工评估</strong></p><table><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">优势</th><th style="text-align:left;">代价与失效场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>离线基准评测</strong></td><td style="text-align:left;">可复现、可回归、变更门禁</td><td style="text-align:left;">数据污染/饱和后与真实能力脱节；覆盖不了长尾分布</td></tr><tr><td style="text-align:left;"><strong>线上评估</strong></td><td style="text-align:left;">真实分布、真实代价信号</td><td style="text-align:left;">反馈稀疏（多数用户不点赞踩）、归因难</td></tr><tr><td style="text-align:left;"><strong>LLM-as-a-Judge</strong></td><td style="text-align:left;">可规模化评开放式产出</td><td style="text-align:left;">偏爱长答案、偏袒同源模型</td></tr><tr><td style="text-align:left;"><strong>人工评估</strong></td><td style="text-align:left;">金标准</td><td style="text-align:left;">贵且慢，只能抽样</td></tr></tbody></table><p>实践姿势：离线基准做变更门禁，线上指标（采纳率/点踩率）做北极星，人工抽样定期校准两者一致性。</p><p><strong>主流评估框架</strong>：</p><ul><li><strong>AgentBench</strong>：涵盖操作系统、数据库、知识图谱等 8 个环境的综合评测。</li><li><strong>GAIA</strong>：评估通用 AI 助手解决现实世界问题的能力。</li><li><strong>SWE-bench</strong>：评估 Agent 在真实 GitHub Issue 上的代码修复能力。</li><li><strong>LangSmith（LangChain）</strong>：提供 trace 分析、评测数据集和 A/B 测试功能。</li></ul><p><strong>真实踩坑案例（离线高分、线上翻车）</strong>：</p><ul><li><strong>现象</strong>：代码 Agent 在内部 SWE-bench 子集上 pass@1 达 34%，上线后开发者满意度只有 20%。</li><li><strong>排查</strong>：两个原因——① 评测用的历史 Issue 可能在模型训练数据中出现过类似修复（数据污染），离线分数虚高；② 离线只测&quot;补丁能否过测试&quot;，不测&quot;补丁是否可采纳&quot;——很多补丁能过测试但风格糟糕、改动面失控，开发者根本不会合入。</li><li><strong>根因</strong>：评测目标（过测试）与业务目标（开发者采纳）错位 + 基准污染。</li><li><strong>修复</strong>：① 自建回归集：150 个新 Issue + 严格隔离训练数据；② 增加人工评审维度（补丁可采纳性）；③ 北极星指标切换为&quot;开发者采纳率&quot;，上线后从 20% 逐步提到 55%。</li></ul><blockquote><p><strong>总结</strong>：Agent 评估不能只看&quot;最终答案对不对&quot;——需要从任务完成率、推理质量、工具准确性、幻觉率、成本效率、安全合规六个维度全面衡量，并用标准化框架（AgentBench/SWE-bench）进行可复现的评测。但公开基准只是起点，与业务目标对齐的私有评测集 + 线上北极星指标才是真正的裁判。</p></blockquote><h4 id="拓展追问-11" tabindex="-1"><a class="header-anchor" href="#拓展追问-11"><span>拓展追问</span></a></h4><ol><li>Agent 评估为什么需要&quot;轨迹级（trajectory）&quot;评估而不只看结果？步骤级评估能额外提供什么？<br> 只看结果是黑盒：同样成功的任务，可能一个 3 步直达、另一个 20 步乱试，成本和稳定性天壤之别；同样失败的任务，失败在第一步选错工具和失败在最后一步总结错误，修复方向完全不同。步骤级评估（工具选择准确率、参数准确率、每步必要性）能定位优化方向，也是回归时区分&quot;能力退化&quot;还是&quot;路径漂移&quot;的唯一手段。</li><li>公开基准的数据污染和饱和怎么处理？<br> 污染：① 优先用发布时间晚于模型训练截止日的新基准；② 自建 holdout 集并严格不进训练管线；③ 对可疑题目做消融验证（删掉疑似见过的题再算分）。饱和：基准分数普遍 90+ 时区分度已丧失，应切换到更难的任务集或自建业务评测集，不要在被刷爆的基准上继续调优。</li><li>业务私有 Agent 评测集从 0 到 1 怎么建？北极星指标怎么选？<br> 路径：① 从线上真实日志抽样 100~300 条任务（分层覆盖高频/长尾/高风险）；② 标注期望结果或评分细则（rubric），关键任务双人标注校验一致性；③ 先跑当前版本得到基线，再定改进目标。北极星选择原则：与业务价值直接挂钩且可度量——客服 Agent 选&quot;自助解决率&quot;而非&quot;回答流畅度&quot;，代码 Agent 选&quot;采纳率&quot;而非&quot;过测试率&quot;。</li></ol><h4 id="场景题-11" tabindex="-1"><a class="header-anchor" href="#场景题-11"><span>场景题</span></a></h4><p>公司客服 Agent 还有 1 个月上线，领导要求你给出&quot;能不能上线&quot;的评估结论。请设计评估方案。</p><p><strong>参考答案</strong>：</p><ul><li><strong>评测集建设（第 1 周）</strong>：从历史客服工单分层抽样 200~300 条真实问题（高频咨询/长尾问题/高风险问题如退款投诉各占比例），标注参考答案与可接受行为（如&quot;应转人工&quot;），关键样本双人标注。</li><li><strong>分层评估（第 2~3 周）</strong>：① 意图识别准确率（门槛 ≥ 95%）；② 工具/检索链路：工具选择准确率、知识检索 Recall@5；③ 端到端：任务完成率、幻觉率（高风险类需 &lt; 0.5‰）、拒答合理性；④ 安全：注入攻击、越权查询、敏感信息泄露的红队测试；⑤ 成本延迟：P95 延迟、单会话 Token 成本。</li><li><strong>上线门槛与分级</strong>：定义硬性门槛（如安全测试零容忍、高风险问题幻觉率达标）与软性门槛（体验类指标达标 80% 即可）；不达硬门槛的功能降级（如退款类直接转人工）而非阻塞整体上线。</li><li><strong>上线后闭环</strong>：小流量灰度 + 线上指标监控（自助解决率、转人工率、点踩率），Bad Case 持续回流评测集；评估不是一次性的上线门禁，而是持续运营的质量体系。</li><li><strong>权衡</strong>：全量人工评估最准但 1 个月做不到，采用&quot;自动裁判全量 + 人工抽样 20% 校准&quot;的组合；结论报告必须分层呈现（哪些能力可上、哪些需降级、风险在哪），而不是一个简单的&quot;能/不能&quot;——这才是专业的评估结论。</li></ul><h3 id="【中等】agent-系统上线后面临哪些工程化挑战-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】agent-系统上线后面临哪些工程化挑战-⭐⭐⭐"><span>【中等】Agent 系统上线后面临哪些工程化挑战？⭐⭐⭐</span></a></h3><table><thead><tr><th style="text-align:left;">挑战</th><th style="text-align:left;">具体问题</th><th style="text-align:left;">应对策略</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>可观测性</strong></td><td style="text-align:left;">Agent 行为是黑盒，难以定位问题</td><td style="text-align:left;">全链路 trace 日志、推理过程可视化</td></tr><tr><td style="text-align:left;"><strong>成本控制</strong></td><td style="text-align:left;">LLM 调用成本高，多步推理 Token 消耗大</td><td style="text-align:left;">Token 预算管理、缓存复用、轻量模型分流</td></tr><tr><td style="text-align:left;"><strong>延迟优化</strong></td><td style="text-align:left;">多轮推理 + 工具调用导致响应慢</td><td style="text-align:left;">并行工具调用、结果缓存、流式输出</td></tr><tr><td style="text-align:left;"><strong>错误恢复</strong></td><td style="text-align:left;">工具调用失败、LLM 输出异常时的容错</td><td style="text-align:left;">重试机制、降级策略、人工兜底</td></tr><tr><td style="text-align:left;"><strong>版本管理</strong></td><td style="text-align:left;">Prompt 变更、模型升级可能导致行为不一致</td><td style="text-align:left;">Prompt 版本控制、A/B 测试、回归测试</td></tr><tr><td style="text-align:left;"><strong>安全合规</strong></td><td style="text-align:left;">数据隐私、输出安全、权限管控</td><td style="text-align:left;">Guardrails、审计日志、数据脱敏</td></tr></tbody></table><blockquote><p><strong>总结</strong>：Agent 工程化的核心挑战是&quot;从 Demo 到 Production&quot;的鸿沟——Demo 只关心&quot;能不能做&quot;，生产系统还必须解决可观测性、成本控制、延迟优化、错误恢复和安全合规等工程问题。</p></blockquote><h3 id="【困难】agent-系统的可观测性如何建设-如何调试-agent-的异常行为-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】agent-系统的可观测性如何建设-如何调试-agent-的异常行为-⭐⭐⭐"><span>【困难】Agent 系统的可观测性如何建设？如何调试 Agent 的异常行为？⭐⭐⭐</span></a></h3><p>Agent 的行为是多步、非确定性的，传统的日志排查难以定位问题，需要专门的可观测体系：</p><p><strong>核心观测对象——Trace（追踪链）</strong>：将一次任务执行展开为树状结构，记录每个节点的输入/输出/耗时/Token 消耗：</p><table><thead><tr><th style="text-align:left;">观测层级</th><th style="text-align:left;">记录内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Session</strong></td><td style="text-align:left;">用户会话级别的完整交互记录</td></tr><tr><td style="text-align:left;"><strong>Agent Run</strong></td><td style="text-align:left;">一次任务的完整执行链路</td></tr><tr><td style="text-align:left;"><strong>LLM 调用</strong></td><td style="text-align:left;">每次推理的完整 Prompt、模型输出、Token 数、延迟</td></tr><tr><td style="text-align:left;"><strong>工具调用</strong></td><td style="text-align:left;">工具名、入参、返回值、成功/失败状态</td></tr><tr><td style="text-align:left;"><strong>护栏触发</strong></td><td style="text-align:left;">Guardrails 拦截事件和原因</td></tr></tbody></table><p><strong>主流工具</strong>：</p><ul><li><strong>LangSmith</strong>：LangChain 官方平台，支持 trace 可视化、回放（Replay）、评测集管理。</li><li><strong>Langfuse</strong>：开源 LLM 可观测平台，支持自部署，提供 trace、评分、成本统计。</li><li><strong>Phoenix（Arize）</strong>：侧重 LLM 评估和 embedding 可视化分析。</li></ul><p><strong>调试方法论</strong>：</p><ol><li><strong>复现</strong>：通过 trace 回放找到异常 Run，逐层检查每步的 Prompt 和输出。</li><li><strong>归因</strong>：区分是 LLM 推理错误、工具返回异常、还是上下文缺失导致的失败。</li><li><strong>固化</strong>：将 Bad Case 沉淀为回归测试集，防止同类问题复发。</li></ol><blockquote><p><strong>总结</strong>：Agent 调试的钥匙是&quot;全链路 Trace&quot;——把每一步的输入输出完整记录下来，配合 LangSmith/Langfuse 等工具回放分析，将黑盒变成白盒。</p></blockquote><h3 id="【中等】如何控制-agent-的运行成本-有哪些-token-优化手段-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】如何控制-agent-的运行成本-有哪些-token-优化手段-⭐⭐⭐"><span>【中等】如何控制 Agent 的运行成本？有哪些 Token 优化手段？⭐⭐⭐</span></a></h3><p>Agent 的多步推理会成倍放大 Token 消耗，成本控制是生产化的关键：</p><table><thead><tr><th style="text-align:left;">手段</th><th style="text-align:left;">原理</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>模型分级路由</strong></td><td style="text-align:left;">简单任务用小模型（如 GPT-4o-mini），复杂任务才调用旗舰模型</td></tr><tr><td style="text-align:left;"><strong>Prompt 缓存</strong></td><td style="text-align:left;">利用 OpenAI/Anthropic 的 Prompt Caching，对重复前缀（系统提示词、工具定义）计费打折</td></tr><tr><td style="text-align:left;"><strong>结果缓存</strong></td><td style="text-align:left;">对相同/相似查询命中缓存（语义缓存，如 GPTCache），跳过 LLM 调用</td></tr><tr><td style="text-align:left;"><strong>上下文精简</strong></td><td style="text-align:left;">对话历史摘要化、工具结果按需注入，减少每轮输入 Token</td></tr><tr><td style="text-align:left;"><strong>限制迭代次数</strong></td><td style="text-align:left;">设置最大轮次和 Token 预算，防止失控循环烧钱</td></tr><tr><td style="text-align:left;"><strong>减少推理链冗余</strong></td><td style="text-align:left;">简单任务关闭 CoT，或用轻量模型做路由/分类等子任务</td></tr></tbody></table><p><strong>度量先行</strong>：先通过可观测平台统计每次任务的 Token 消耗分布（哪一步最贵），再针对性优化。</p><blockquote><p><strong>总结</strong>：Agent 成本控制的核心思路是&quot;能不调就不调、能小模型就不大模型、能缓存就不重算&quot;——模型路由 + Prompt 缓存 + 预算兜底是性价比最高的三板斧。</p></blockquote><h3 id="【中等】agent-执行代码等高风险操作时-沙箱-sandbox-安全如何设计-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】agent-执行代码等高风险操作时-沙箱-sandbox-安全如何设计-⭐⭐⭐"><span>【中等】Agent 执行代码等高风险操作时，沙箱（Sandbox）安全如何设计？⭐⭐⭐</span></a></h3><p>Agent 具备代码执行、文件操作等能力后，必须用<strong>沙箱隔离</strong>防止恶意或意外行为破坏宿主环境。</p><p><strong>核心威胁</strong>：</p><ul><li>执行恶意代码（注入攻击诱导 Agent 运行危险命令）。</li><li>越权访问（读取敏感文件、访问内网资源）。</li><li>资源耗尽（无限循环、海量请求）。</li></ul><p><strong>沙箱设计要点</strong>：</p><table><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">措施</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>执行隔离</strong></td><td style="text-align:left;">代码在容器（Docker）、microVM（如 gVisor/Firecracker）或 WebAssembly 中运行，与宿主隔离</td></tr><tr><td style="text-align:left;"><strong>文件系统</strong></td><td style="text-align:left;">限制只能访问指定的工作目录，只读挂载敏感路径</td></tr><tr><td style="text-align:left;"><strong>网络限制</strong></td><td style="text-align:left;">默认禁止外网访问，或白名单制放行特定域名</td></tr><tr><td style="text-align:left;"><strong>资源限额</strong></td><td style="text-align:left;">CPU、内存、执行时间、输出大小设置上限</td></tr><tr><td style="text-align:left;"><strong>权限最小化</strong></td><td style="text-align:left;">沙箱内以非特权用户运行，不提供 root、不挂载宿主任何凭据</td></tr></tbody></table><p><strong>典型实现</strong>：E2B（云端代码沙箱）、Docker + 资源限制、浏览器 Agent 用隔离的无头浏览器会话。</p><blockquote><p><strong>总结</strong>：沙箱的核心原则是&quot;默认不可信 + 隔离执行 + 资源限额&quot;——把 Agent 当作不可信的第三方代码对待，宁可限制能力也不开放边界。</p></blockquote><h3 id="【中等】多-agent-系统中如何管理-agent-间的上下文传递-⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】多-agent-系统中如何管理-agent-间的上下文传递-⭐⭐"><span>【中等】多 Agent 系统中如何管理 Agent 间的上下文传递？⭐⭐</span></a></h3><p>多 Agent 协作时，上下文传递是效率和正确性的关键矛盾：传递太少导致信息丢失，传递太多导致上下文污染和成本飙升。</p><p><strong>常见模式</strong>：</p><table><thead><tr><th style="text-align:left;">模式</th><th style="text-align:left;">原理</th><th style="text-align:left;">优劣</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>全量传递</strong></td><td style="text-align:left;">将完整对话历史传给下一个 Agent</td><td style="text-align:left;">信息完整，但上下文膨胀快、成本高</td></tr><tr><td style="text-align:left;"><strong>摘要传递</strong></td><td style="text-align:left;">上游 Agent 生成结构化摘要（结论 + 关键事实），下游只接收摘要</td><td style="text-align:left;">上下文精简，但可能丢失细节</td></tr><tr><td style="text-align:left;"><strong>工件传递</strong></td><td style="text-align:left;">结果写入共享存储（文件/数据库），仅传递引用（如 A2A Artifact）</td><td style="text-align:left;">上下文最精简，适合大体积产出物</td></tr><tr><td style="text-align:left;"><strong>黑板模式</strong></td><td style="text-align:left;">所有 Agent 读写共享的&quot;黑板&quot;（Blackboard）状态空间</td><td style="text-align:left;">解耦彻底，需设计并发读写规则</td></tr></tbody></table><p><strong>实践建议</strong>：</p><ul><li>默认用&quot;摘要 + 工件&quot;组合：关键结论进摘要，大体积数据进共享存储按需读取。</li><li>为 Agent 间消息定义统一的 Schema（如 A2A 的 Message/Artifact），避免自由文本传递造成信息失真。</li><li>主 Agent 只接收子 Agent 的结果摘要，不接收其完整推理过程（上下文隔离）。</li></ul><blockquote><p><strong>总结</strong>：多 Agent 上下文管理的核心是&quot;传结论不传过程、传引用不传全文&quot;——用结构化交接替代全量历史，既控成本又保信息密度。</p></blockquote>',365)])])}const i=e(s,[["render",r]]),h=JSON.parse('{"path":"/pages/e475ebc6/","title":"AI Agent 面试","lang":"zh-CN","frontmatter":{"title":"AI Agent 面试","date":"2026-07-29T23:10:31.000Z","categories":["人工智能"],"tags":["人工智能","AI","Agent"],"permalink":"/pages/e475ebc6/","description":"AI Agent 面试 基础概念与核心组件 【简单】什么是 AI Agent？它和直接调用大模型 API 有什么区别？⭐⭐⭐ AI Agent（智能体）是以大语言模型（LLM）为\\"大脑\\"的自主智能系统，能以\\"用户目标 → Agent 规划 → Agent 执行 → 结果反馈\\"的模式自主完成复杂任务。 与直接调用大模型 API 的核心区别： 方案权衡：A...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"AI Agent 面试\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2026-07-29T23:10:31.000Z\\",\\"dateModified\\":\\"2026-08-09T08:30:39.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"钝悟\\",\\"url\\":\\"https://dunwu.github.io/waterdrop\\"}]}"],["meta",{"property":"og:url","content":"https://dunwu.github.io/waterdrop/waterdrop/pages/e475ebc6/"}],["meta",{"property":"og:site_name","content":"钝悟"}],["meta",{"property":"og:title","content":"AI Agent 面试"}],["meta",{"property":"og:description","content":"AI Agent 面试 基础概念与核心组件 【简单】什么是 AI Agent？它和直接调用大模型 API 有什么区别？⭐⭐⭐ AI Agent（智能体）是以大语言模型（LLM）为\\"大脑\\"的自主智能系统，能以\\"用户目标 → Agent 规划 → Agent 执行 → 结果反馈\\"的模式自主完成复杂任务。 与直接调用大模型 API 的核心区别： 方案权衡：A..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-08-09T08:30:39.000Z"}],["meta",{"property":"article:tag","content":"Agent"}],["meta",{"property":"article:tag","content":"AI"}],["meta",{"property":"article:tag","content":"人工智能"}],["meta",{"property":"article:published_time","content":"2026-07-29T23:10:31.000Z"}],["meta",{"property":"article:modified_time","content":"2026-08-09T08:30:39.000Z"}]]},"git":{"createdTime":1785371293000,"updatedTime":1786264239000,"contributors":[{"name":"dunwu","username":"dunwu","email":"forbreak@163.com","commits":2,"url":"https://github.com/dunwu"}]},"readingTime":{"minutes":85.83,"words":25750},"filePathRelative":"17.人工智能/Agent面试.md","excerpt":"\\n<h2>基础概念与核心组件</h2>\\n<h3>【简单】什么是 AI Agent？它和直接调用大模型 API 有什么区别？⭐⭐⭐</h3>\\n<p>AI Agent（智能体）是以大语言模型（LLM）为\\"大脑\\"的自主智能系统，能以\\"<strong>用户目标 → Agent 规划 → Agent 执行 → 结果反馈</strong>\\"的模式自主完成复杂任务。</p>\\n<p><strong>与直接调用大模型 API 的核心区别</strong>：</p>\\n<table>\\n<thead>\\n<tr>\\n<th style=\\"text-align:left\\">维度</th>\\n<th style=\\"text-align:left\\">AI Agent</th>\\n<th style=\\"text-align:left\\">直接调用 LLM API</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td style=\\"text-align:left\\"><strong>交互模式</strong></td>\\n<td style=\\"text-align:left\\">多步骤自主循环（规划→执行→反思）</td>\\n<td style=\\"text-align:left\\">单次问答（指令→生成→用户执行）</td>\\n</tr>\\n<tr>\\n<td style=\\"text-align:left\\"><strong>工具能力</strong></td>\\n<td style=\\"text-align:left\\">自主调用外部工具（搜索、API 等）</td>\\n<td style=\\"text-align:left\\">仅生成文本，无法执行操作</td>\\n</tr>\\n<tr>\\n<td style=\\"text-align:left\\"><strong>记忆能力</strong></td>\\n<td style=\\"text-align:left\\">具备短期/长期记忆，持续学习适应</td>\\n<td style=\\"text-align:left\\">无状态，每次独立交互</td>\\n</tr>\\n<tr>\\n<td style=\\"text-align:left\\"><strong>自主性</strong></td>\\n<td style=\\"text-align:left\\">主动拆解目标、动态调整计划</td>\\n<td style=\\"text-align:left\\">被动应答，依赖用户逐步指令</td>\\n</tr>\\n</tbody>\\n</table>","autoDesc":true}');export{i as comp,h as data};
